import { GoogleGenAI, Type, GenerateContentResponse, Part } from "@google/genai";
import { ProductInfo, AdAngle } from "../types";
import { brandArchetypes } from "../data/brandArchetypes";

// Helper to get a fresh instance for each API call, required for correct API key usage.
const getGenAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateAdAngles = async (productInfo: ProductInfo): Promise<AdAngle[]> => {
  const ai = getGenAI();
  // Using gemini-3-pro-preview for complex reasoning and marketing strategy.
  const model = "gemini-3-pro-preview";

  let brandContext = '';
  if (productInfo.brandArchetype && brandArchetypes[productInfo.brandArchetype]) {
    const archetype = brandArchetypes[productInfo.brandArchetype];
    brandContext = `
    Brand Identity:
    - Archetype: ${archetype.name}
    - Vibe: ${archetype.vibe}
    - Tone: ${archetype.tone}
    - Reference Brands: ${archetype.examples.join(', ')}
    - Core Values: ${archetype.description}
    `;
  }

  const prompt = `
    You are a world-class Direct Response Marketing Strategist. Your goal is to solve "Creative Fatigue" for a brand.
    You must generate 5 fresh, high-performing ad angles that interrupt the scroll and use deep psychological triggers.

    Product Details:
    - Name: ${productInfo.name}
    - Audience: ${productInfo.audience}
    - USPs: ${productInfo.sellingPoints}
    - Objective: ${productInfo.goal}
    - Platform: ${productInfo.platform}
    ${brandContext}

    Instructions:
    1. Avoid "boring" or standard ad angles. Focus on "Pattern Interruption".
    2. Consider angles like: "The Contrast Effect", "Social Proof Overload", "The Us vs Them", "The Discovery/How-To", or "Aspirational Lifestyle".
    3. For each angle, provide a title, a brief strategic description, and a specific visual prompt idea.

    Return the result as a JSON array.
  `;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 16000 }, // Enable deep reasoning for better creativity
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              visual_prompt_idea: { type: Type.STRING },
            },
            required: ["title", "description", "visual_prompt_idea"],
          },
        },
      },
    });

    return JSON.parse(response.text.trim());
  } catch (error) {
    console.error("Error generating ad angles:", error);
    throw new Error("Failed to generate ad angles. Please check your network and API key.");
  }
};

export const generateAdVisuals = async (
  angle: AdAngle,
  baseImage: { data: string; mimeType: string },
  customPrompt: string,
  options: {
    numberOfImages: number;
    aspectRatio: string;
    useSuperRealism: boolean;
    styleReference?: { data: string; mimeType: string };
    headline?: string;
    platform: string;
    textStyle: string;
  }
): Promise<string[]> => {
  const ai = getGenAI();
  // Using gemini-3-pro-image-preview for high-quality ad visuals.
  const model = "gemini-3-pro-image-preview";

  // Extract ratio string like '1:1' or '9:16'
  const ratio = options.aspectRatio.includes('1:1') ? '1:1' : 
                options.aspectRatio.includes('9:16') ? '9:16' : 
                options.aspectRatio.includes('16:9') ? '16:9' : '1:1';

  try {
    const imagePromises = Array.from({ length: options.numberOfImages }, () => {
      let realismPart = '';
      if (options.useSuperRealism) {
        realismPart = `
          STYLE: Professional advertising photography. 
          CAMERA: 8k resolution, shot on Phase One XF, 80mm lens, f/8 for sharpness. 
          LIGHTING: High-end studio lighting, soft shadows, premium commercial aesthetic.
        `;
      }

      let textOverlayPart = '';
      if (options.headline) {
        textOverlayPart = `
          TEXT OVERLAY: Include the text "${options.headline}". 
          STYLE: ${options.textStyle}. Ensure the text is perfectly legible, professionally kerned, and integrated into the composition like a high-end magazine ad.
        `;
      }

      const fullPrompt = `
        TASK: Act as a Creative Director. Repurpose the provided product image into a high-converting ad for ${options.platform}.

        AD ANGLE: ${angle.title} - ${angle.description}
        USER INSTRUCTION: ${customPrompt}
        ${realismPart}
        ${textOverlayPart}

        CORE REQUIREMENT: The product in the first image MUST be the focal point. Maintain its exact branding and form. 
        CONTEXT: Place it in a new, exciting environment that matches the ad angle.
        ${options.styleReference ? "AESTHETIC: Mirror the color palette, mood, and lighting of the second provided image." : ""}
      `;

      const parts: Part[] = [
        { inlineData: { data: baseImage.data, mimeType: baseImage.mimeType } },
      ];

      if (options.styleReference) {
        parts.push({ inlineData: { data: options.styleReference.data, mimeType: options.styleReference.mimeType } });
      }

      parts.push({ text: fullPrompt });

      return ai.models.generateContent({
        model: model,
        contents: { parts },
        config: {
          imageConfig: {
            aspectRatio: ratio as any,
            imageSize: "1K"
          }
        },
      });
    });

    const responses = await Promise.all(imagePromises);

    const base64Images: string[] = [];
    for (const res of responses) {
      const part = res.candidates[0].content.parts.find(p => p.inlineData);
      if (part?.inlineData?.data) {
        base64Images.push(part.inlineData.data);
      }
    }

    if (base64Images.length === 0) {
      throw new Error("No images were returned by the model.");
    }

    return base64Images;

  } catch (error) {
    console.error("Error generating ad visuals:", error);
    throw new Error("Visual generation failed. This model might be busy or the prompt triggered a safety filter.");
  }
};

export const generateAdVideo = async (
  angle: AdAngle,
  baseImage: { data: string; mimeType: string } | null,
  customPrompt: string,
  options: {
    resolution: '720p' | '1080p';
    aspectRatio: '16:9' | '9:16';
  }
): Promise<string> => {
  const ai = getGenAI();
  const model = 'veo-3.1-fast-generate-preview';

  try {
    let operation = await ai.models.generateVideos({
      model: model,
      prompt: `Premium commercial for ${angle.title}. ${customPrompt}. High-end cinematography, fluid motion, professional color grade.`,
      image: baseImage ? { imageBytes: baseImage.data, mimeType: baseImage.mimeType } : undefined,
      config: {
        numberOfVideos: 1,
        resolution: options.resolution,
        aspectRatio: options.aspectRatio,
      }
    });

    while (!operation.done) {
      await new Promise(resolve => setTimeout(resolve, 8000));
      operation = await ai.operations.getVideosOperation({ operation: operation });
    }

    if (operation.error) {
      throw new Error(operation.error.message);
    }

    const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
    if (!downloadLink) {
      throw new Error("Video generated but no link found.");
    }

    const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
    if (!response.ok) throw new Error("Failed to fetch video bytes.");

    const blob = await response.blob();
    return URL.createObjectURL(blob);

  } catch (error) {
    console.error("Error in generateAdVideo:", error);
    const msg = error instanceof Error ? error.message : "Unknown video error";
    if (msg.includes("Requested entity was not found")) {
      throw new Error("API Key configuration error. Please re-select your paid project key.");
    }
    throw new Error(`Video generation failed: ${msg}`);
  }
};

export const generateCaptions = async (productInfo: ProductInfo, angle: AdAngle): Promise<string[]> => {
  const ai = getGenAI();
  const model = "gemini-3-flash-preview";

  const prompt = `
    Write 3 high-converting social media captions for this ad.
    Angle: ${angle.title}
    Product: ${productInfo.name}
    Audience: ${productInfo.audience}
    Platform: ${productInfo.platform}

    Rules:
    - 1 Short & Punchy
    - 1 Story-based
    - 1 Direct & Benefit-driven
    - Use relevant emojis and hashtags.
    - Tailor the tone to the ${productInfo.platform} culture.
  `;

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: { type: Type.STRING },
        },
      },
    });
    return JSON.parse(response.text.trim());
  } catch (error) {
    console.error("Caption error:", error);
    throw new Error("Failed to generate captions.");
  }
};

import React, { useState, useCallback, ChangeEvent, useEffect, useRef } from 'react';
import { AppStep, ProductInfo, AdAngle, UploadedFile, GenerationMode } from './types';
import { CAMPAIGN_GOALS } from './constants';
import { brandArchetypes } from './data/brandArchetypes';
import { generateAdAngles, generateAdVisuals, generateCaptions, generateAdVideo } from './services/geminiService';
import SparklesIcon from './components/icons/SparklesIcon';
import UploadIcon from './components/icons/UploadIcon';
import DownloadIcon from './components/icons/DownloadIcon';
import CopyIcon from './components/icons/CopyIcon';
import Loader from './components/Loader';
import VideoIcon from './components/icons/VideoIcon';

// For CDN-loaded libraries
declare var JSZip: any;
declare var saveAs: any;
declare var window: any;

const STEPS = [
    { id: AppStep.DEFINE_PRODUCT, name: 'Define' },
    { id: AppStep.GENERATE_ANGLES, name: 'Angle' },
    { id: AppStep.GENERATE_VISUALS, name: 'Visuals' },
];

const VIDEO_LOADING_MESSAGES = [
  "Initializing cinematic engine...",
  "Analyzing product geometry for motion...",
  "Simulating studio lighting environments...",
  "Crafting high-fidelity transitions...",
  "Optimizing for scroll-stopping impact...",
  "Applying final color grading...",
  "Almost there! Polishing the frames..."
];

interface StepperProps {
  currentStepEnum: AppStep;
  onStepClick: (stepId: AppStep) => void;
}

const Stepper: React.FC<StepperProps> = ({ currentStepEnum, onStepClick }) => {
    const activeSteps = [AppStep.DEFINE_PRODUCT, AppStep.GENERATE_ANGLES, AppStep.GENERATE_VISUALS];
    if (!activeSteps.includes(currentStepEnum)) return null;

    const currentStepIndex = STEPS.findIndex(s => s.id === currentStepEnum);

    return (
        <nav className="flex items-center justify-center" aria-label="Progress">
            <ol role="list" className="flex items-center space-x-2 md:space-x-4">
                {STEPS.map((step, stepIdx) => {
                    const isCompleted = stepIdx < currentStepIndex;
                    const isCurrent = stepIdx === currentStepIndex;
                     const statusClasses = isCompleted 
                        ? 'text-brand-primary hover:text-indigo-400' 
                        : isCurrent 
                        ? 'text-brand-primary' 
                        : 'text-content-secondary';

                    return (
                        <li key={step.name} 
                            onClick={() => isCompleted && onStepClick(step.id)} 
                            className={`flex items-center ${isCompleted ? 'cursor-pointer' : ''} ${stepIdx < STEPS.length - 1 ? 'w-24 md:w-32' : ''}`}
                        >
                             <div className={`flex items-center text-sm font-semibold ${statusClasses} transition-colors`}>
                                <span className={`flex h-8 w-8 flex-shrink-0 items-center justify-center rounded-full ${isCompleted || isCurrent ? 'bg-brand-primary' : 'bg-surface border-2 border-border'}`}>
                                    {isCompleted ? (
                                        <svg className="h-5 w-5 text-white" viewBox="0 0 20 20" fill="currentColor" aria-hidden="true">
                                            <path fillRule="evenodd" d="M16.704 4.153a.75.75 0 01.143 1.052l-8 10.5a.75.75 0 01-1.127.075l-4.5-4.5a.75.75 0 011.06-1.06l3.894 3.893 7.48-9.817a.75.75 0 011.052-.143z" clipRule="evenodd" />
                                        </svg>
                                    ) : (
                                        <span className={isCurrent ? 'text-white' : 'text-content-secondary'}>{`0${stepIdx + 1}`}</span>
                                    )}
                                </span>
                                <span className="ml-2 hidden md:inline">{step.name}</span>
                            </div>
                            {stepIdx < STEPS.length - 1 && (
                                <div className="h-0.5 w-full bg-border ml-2 md:ml-4" />
                            )}
                        </li>
                    )
                })}
            </ol>
        </nav>
    );
};

const FileUploader: React.FC<{
    id: string;
    label: string;
    uploadedFile: UploadedFile | null;
    onFileProcessed: (file: UploadedFile) => void;
    onError: (message: string) => void;
}> = ({ id, label, uploadedFile, onFileProcessed, onError }) => {
    const [isDraggingOver, setIsDraggingOver] = useState(false);

    const processFile = (file: File) => {
        if (file && file.type.startsWith('image/')) {
            const reader = new FileReader();
            reader.onloadend = () => {
                const base64String = (reader.result as string).split(',')[1];
                onFileProcessed({ file, data: base64String, mimeType: file.type });
            };
            reader.readAsDataURL(file);
            onError('');
        } else {
            onError('Please upload a valid image file (e.g., PNG, JPG, WEBP).');
        }
    };

    const handleFileChange = (e: ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) processFile(file);
    };

    const handleDragOver = (e: React.DragEvent<HTMLLabelElement>) => { e.preventDefault(); e.stopPropagation(); };
    const handleDragEnter = (e: React.DragEvent<HTMLLabelElement>) => { e.preventDefault(); e.stopPropagation(); setIsDraggingOver(true); };
    const handleDragLeave = (e: React.DragEvent<HTMLLabelElement>) => { e.preventDefault(); e.stopPropagation(); setIsDraggingOver(false); };
    const handleDrop = (e: React.DragEvent<HTMLLabelElement>) => {
        e.preventDefault();
        e.stopPropagation();
        setIsDraggingOver(false);
        const file = e.dataTransfer.files?.[0];
        if (file) processFile(file);
    };

    return (
        <div>
            <label className="block mb-2 font-semibold text-sm text-content-secondary">{label}</label>
            <label
                htmlFor={id}
                onDragEnter={handleDragEnter}
                onDragLeave={handleDragLeave}
                onDragOver={handleDragOver}
                onDrop={handleDrop}
                className={`relative flex flex-col items-center justify-center border-2 border-dashed rounded-lg p-6 text-center cursor-pointer transition-colors ${
                    isDraggingOver ? 'border-brand-primary bg-brand-primary/10' : 'border-border hover:border-brand-primary'
                }`}
            >
                <input id={id} type="file" onChange={handleFileChange} accept="image/*" className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" />
                <UploadIcon className="mx-auto w-8 h-8 text-content-secondary mb-2" />
                {uploadedFile ? (
                    <p className="text-brand-primary text-sm">{uploadedFile.file.name}</p>
                ) : isDraggingOver ? (
                    <p className="text-brand-primary font-semibold text-sm">Drop image to upload</p>
                ) : (
                    <p className="text-content-secondary text-sm">Click to upload or drag & drop</p>
                )}
            </label>
            {uploadedFile && <img src={URL.createObjectURL(uploadedFile.file)} alt="Preview" className="mt-4 rounded-lg max-h-32 w-auto mx-auto border border-border" />}
        </div>
    );
};


const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.LANDING);
  const [productInfo, setProductInfo] = useState<ProductInfo>({
    name: '',
    audience: '',
    sellingPoints: '',
    goal: CAMPAIGN_GOALS[0],
    brandArchetype: '',
    platform: 'Instagram'
  });
  const [adAngles, setAdAngles] = useState<AdAngle[]>([]);
  const [selectedAngle, setSelectedAngle] = useState<AdAngle | null>(null);
  const [generationMode, setGenerationMode] = useState<GenerationMode>('Image');
  const [uploadedAsset, setUploadedAsset] = useState<UploadedFile | null>(null);
  const [styleReferenceAsset, setStyleReferenceAsset] = useState<UploadedFile | null>(null);
  const [headlineText, setHeadlineText] = useState('');
  const [textStyle, setTextStyle] = useState('Classic');
  const [customPrompt, setCustomPrompt] = useState('');
  const [imageOptions, setImageOptions] = useState({ aspectRatio: 'Square (1:1)', count: 3 });
  const [videoOptions, setVideoOptions] = useState({ aspectRatio: 'Portrait (9:16)', resolution: '720p' });
  const [generatedImages, setGeneratedImages] = useState<string[]>([]);
  const [generatedVideoUrl, setGeneratedVideoUrl] = useState<string | null>(null);
  const [captions, setCaptions] = useState<string[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [loadingMessage, setLoadingMessage] = useState('');
  const [isGeneratingCaptions, setIsGeneratingCaptions] = useState(false);
  const [copiedCaptionIndex, setCopiedCaptionIndex] = useState<number | null>(null);
  const [isZipping, setIsZipping] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [useSuperRealism, setUseSuperRealism] = useState(true);
  const [isApiKeyReady, setIsApiKeyReady] = useState(false);
  const [isCheckingApiKey, setIsCheckingApiKey] = useState(true);

  const videoMessageInterval = useRef<number | null>(null);

  useEffect(() => {
    const checkKey = async () => {
        if (window.aistudio && await window.aistudio.hasSelectedApiKey()) {
            setIsApiKeyReady(true);
        }
        setIsCheckingApiKey(false);
    };
    checkKey();
  }, []);

  const handleSelectKey = async () => {
    if (window.aistudio) {
        try {
            await window.aistudio.openSelectKey();
            setIsApiKeyReady(true);
        } catch (e) {
            console.error("Error opening API key selection:", e);
        }
    }
  };

  const startVideoLoadingRotation = () => {
    let index = 0;
    setLoadingMessage(VIDEO_LOADING_MESSAGES[0]);
    videoMessageInterval.current = window.setInterval(() => {
        index = (index + 1) % VIDEO_LOADING_MESSAGES.length;
        setLoadingMessage(VIDEO_LOADING_MESSAGES[index]);
    }, 15000);
  };

  const stopVideoLoadingRotation = () => {
    if (videoMessageInterval.current) {
        clearInterval(videoMessageInterval.current);
        videoMessageInterval.current = null;
    }
  };

  const handleCopyCaption = useCallback((caption: string, index: number) => {
    navigator.clipboard.writeText(caption);
    setCopiedCaptionIndex(index);
    setTimeout(() => setCopiedCaptionIndex(null), 2000);
  }, []);

  const handleInputChange = useCallback((e: ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setProductInfo((prev) => ({ ...prev, [name]: value }));
  }, []);

  const handleImageOptionChange = useCallback((e: ChangeEvent<HTMLSelectElement>) => {
    const { name, value } = e.target;
    setImageOptions(prev => ({ ...prev, [name]: name === 'count' ? parseInt(value, 10) : value }));
  }, []);

  const handleVideoOptionChange = useCallback((e: ChangeEvent<HTMLSelectElement>) => {
    const { name, value } = e.target;
    setVideoOptions(prev => ({ ...prev, [name]: value }));
  }, []);

  const handleStepClick = (targetStep: AppStep) => {
    const currentStepIndex = STEPS.findIndex(s => s.id === step);
    const targetStepIndex = STEPS.findIndex(s => s.id === targetStep);

    if (targetStepIndex >= currentStepIndex) return;
    setStep(targetStep);
  };

  const startAngleGeneration = async () => {
    setIsLoading(true);
    setLoadingMessage("Strategizing unique ad angles with deep reasoning...");
    setError(null);
    try {
      const angles = await generateAdAngles(productInfo);
      setAdAngles(angles);
      setStep(AppStep.GENERATE_ANGLES);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred.');
    } finally {
      setIsLoading(false);
    }
  };

  const startGeneration = async () => {
    if (generationMode === 'Image') {
        startImageGeneration();
    } else {
        startVideoGeneration();
    }
  };

  const startImageGeneration = async () => {
    if (!selectedAngle || !uploadedAsset) return;
    setIsLoading(true);
    setLoadingMessage("Generating high-fidelity visual variations...");
    setError(null);
    setGeneratedImages([]);
    setGeneratedVideoUrl(null);
    try {
      const imagesB64 = await generateAdVisuals(
        selectedAngle, 
        uploadedAsset, 
        customPrompt, 
        {
            numberOfImages: imageOptions.count, 
            aspectRatio: imageOptions.aspectRatio,
            useSuperRealism: useSuperRealism,
            styleReference: styleReferenceAsset || undefined,
            headline: headlineText,
            platform: productInfo.platform,
            textStyle: textStyle
        }
      );
      setGeneratedImages(imagesB64);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Visual generation failed.');
    } finally {
      setIsLoading(false);
    }
  };

  const startVideoGeneration = async () => {
    if (!selectedAngle) return;
    setIsLoading(true);
    startVideoLoadingRotation();
    setError(null);
    setGeneratedImages([]);
    setGeneratedVideoUrl(null);
    try {
        const videoUrl = await generateAdVideo(
            selectedAngle,
            uploadedAsset,
            customPrompt,
            {
                aspectRatio: videoOptions.aspectRatio.includes('9:16') ? '9:16' : '16:9',
                resolution: videoOptions.resolution as '720p' | '1080p'
            }
        );
        setGeneratedVideoUrl(videoUrl);
    } catch (err) {
        const errorMessage = err instanceof Error ? err.message : 'Video generation failed.';
        setError(errorMessage);
        if (errorMessage.includes("API key")) setIsApiKeyReady(false);
    } finally {
        stopVideoLoadingRotation();
        setIsLoading(false);
    }
  };

  const startCaptionGeneration = async () => {
    if (!selectedAngle) return;
    setIsGeneratingCaptions(true);
    try {
        const generatedCaps = await generateCaptions(productInfo, selectedAngle);
        setCaptions(generatedCaps);
    } catch (err) {
        setError("Failed to generate captions.");
    } finally {
        setIsGeneratingCaptions(false);
    }
  };

  const handleDownloadAll = async () => {
    if (generatedImages.length === 0) return;
    setIsZipping(true);
    try {
      const zip = new JSZip();
      generatedImages.forEach((imgBase64, index) => {
        zip.file(`ad-variation-${index + 1}.png`, imgBase64, { base64: true });
      });
      const blob = await zip.generateAsync({ type: 'blob' });
      saveAs(blob, 'ad-creatives.zip');
    } catch (err) {
      setError("Issue creating zip file.");
    } finally {
      setIsZipping(false);
    }
  };

  const resetApp = () => {
    setStep(AppStep.LANDING);
    setProductInfo({ name: '', audience: '', sellingPoints: '', goal: CAMPAIGN_GOALS[0], brandArchetype: '', platform: 'Instagram' });
    setAdAngles([]);
    setSelectedAngle(null);
    setUploadedAsset(null);
    setStyleReferenceAsset(null);
    setHeadlineText('');
    setTextStyle('Classic');
    setCustomPrompt('');
    setGeneratedImages([]);
    setGeneratedVideoUrl(null);
    setCaptions([]);
    setError(null);
  };

  if (isCheckingApiKey) {
    return <div className="min-h-screen w-full flex items-center justify-center bg-background"><Loader message="Authenticating Creative Catalyst..." /></div>;
  }

  if (!isApiKeyReady) {
    return (
        <div className="min-h-screen w-full flex flex-col items-center justify-center p-4 text-center bg-background">
            <div className="p-8 bg-surface border border-border rounded-3xl shadow-2xl max-w-lg">
                <VideoIcon className="w-16 h-16 text-brand-primary mx-auto mb-6" />
                <h1 className="text-3xl font-bold mb-4 text-content-primary">Activation Required</h1>
                <p className="text-content-secondary mb-8">
                    To access the high-performance Gemini 3 and Veo Video engines, you must select an API key from a paid Google Cloud project.
                    <br/><br/>
                    <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noopener noreferrer" className="text-brand-primary hover:underline">View Billing Details</a>
                </p>
                <button onClick={handleSelectKey} className="w-full bg-gradient-to-r from-brand-primary to-brand-secondary text-white font-bold py-4 px-8 rounded-2xl text-lg hover:scale-[1.02] active:scale-[0.98] transition-all duration-200">
                    Select API Key to Begin
                </button>
            </div>
        </div>
    );
  }

  const renderLanding = () => (
    <div className="text-center max-w-4xl mx-auto py-12">
      <div className="inline-block p-6 bg-brand-primary/10 rounded-3xl mb-8 shadow-2xl border border-brand-primary/20">
        <SparklesIcon className="w-16 h-16 text-brand-primary" />
      </div>
