        <SparklesIcon className="w-16 h-16 text-brand-primary" />
      </div>
      <h1 className="text-5xl md:text-7xl font-bold tracking-tight text-content-primary mb-6 bg-clip-text text-transparent bg-gradient-to-r from-content-primary via-indigo-200 to-content-primary">Creative Catalyst</h1>
      <p className="text-xl md:text-2xl text-content-secondary mb-12 max-w-2xl mx-auto leading-relaxed">
