                <input name="sellingPoints" value={productInfo.sellingPoints} onChange={handleInputChange} className="w-full p-4 bg-background border border-border rounded-xl focus:ring-2 focus:ring-brand-primary focus:outline-none transition-all" placeholder="e.g., Organic, Cruelty-free, 24h hydration" />
