const Stepper: React.FC<{ currentStepEnum: AppStep, onStepClick: (s: AppStep) => void }> = ({ currentStepEnum, onStepClick }) => {
    const steps = [AppStep.DEFINE_PRODUCT, AppStep.GENERATE_ANGLES, AppStep.GENERATE_VISUALS];
    if (!steps.includes(currentStepEnum)) return null;
    const labels = ["Define", "Angle", "Visuals"];
    return (
        <nav className="flex items-center justify-center space-x-8">
            {steps.map((s, i) => (
                <div key={i} className={`flex items-center text-sm font-semibold transition-colors ${currentStepEnum === s ? 'text-brand-primary' : 'text-content-secondary cursor-pointer'}`} onClick={() => i < steps.indexOf(currentStepEnum) && onStepClick(s)}>
                    <span className={`h-8 w-8 flex items-center justify-center rounded-full mr-2 ${currentStepEnum === s ? 'bg-brand-primary text-white' : 'bg-surface border-border border'}`}>{i+1}</span>
                    <span className="hidden md:inline">{labels[i]}</span>
                </div>
            ))}
        </nav>
    );
};

const FileUploader: React.FC<{ id: string, label: string, uploadedFile: UploadedFile | null, onFileProcessed: (f: UploadedFile) => void, onError: (m: string) => void }> = ({ id, label, uploadedFile, onFileProcessed, onError }) => {
    const processFile = (file: File) => {
        if (file && file.type.startsWith('image/')) {
            const reader = new FileReader();
            reader.onloadend = () => {
                const base64 = (reader.result as string).split(',')[1];
                onFileProcessed({ file, data: base64, mimeType: file.type });
            };
            reader.readAsDataURL(file);
        }
    };
    return (
        <div className="w-full">
            <label className="block mb-2 font-semibold text-sm text-content-secondary">{label}</label>
            <label htmlFor={id} className="relative flex flex-col items-center justify-center border-2 border-dashed border-border rounded-lg p-6 cursor-pointer hover:border-brand-primary transition-colors">
                <input id={id} type="file" onChange={(e) => e.target.files?.[0] && processFile(e.target.files[0])} accept="image/*" className="hidden" />
                <UploadIcon className="w-8 h-8 text-content-secondary mb-2" />
                <p className="text-sm">{uploadedFile ? uploadedFile.file.name : "Upload image"}</p>
                {uploadedFile && <img src={URL.createObjectURL(uploadedFile.file)} className="mt-4 max-h-32 rounded-lg" />}
            </label>
        </div>
    );
};

