const Stepper: React.FC<{ currentStepEnum: AppStep, onStepClick: (s: AppStep) => void }> = ({ currentStepEnum, onStepClick }) => {
    const steps = [AppStep.DEFINE_PRODUCT, AppStep.GENERATE_ANGLES, AppStep.GENERATE_VISUALS];
    if (!steps.includes(currentStepEnum)) return null;
    const labels = ["Define", "Angle", "Visuals"];
    return (
        <nav className="flex items-center justify-center space-x-4 md:space-x-12">
            {steps.map((s, i) => {
                const isActive = currentStepEnum === s;
                const isCompleted = steps.indexOf(currentStepEnum) > i;
                return (
                    <div key={i} className={`flex items-center text-sm font-semibold transition-all ${isActive ? 'text-brand-primary' : isCompleted ? 'text-indigo-300' : 'text-content-secondary'}`}>
                        <span className={`h-10 w-10 flex items-center justify-center rounded-full mr-3 border-2 transition-all ${isActive ? 'bg-brand-primary text-white border-brand-primary shadow-[0_0_20px_rgba(129,140,248,0.4)]' : isCompleted ? 'bg-indigo-900/30 border-brand-primary text-brand-primary' : 'bg-surface border-border'}`}>{i+1}</span>
                        <span className="hidden md:inline text-base">{labels[i]}</span>
                    </div>
                );
            })}
        </nav>
    );
};

const FileUploader: React.FC<{ id: string, label: string, uploadedFile: UploadedFile | null, onFileProcessed: (f: UploadedFile) => void, onError: (m: string) => void, compact?: boolean }> = ({ id, label, uploadedFile, onFileProcessed, onError, compact }) => {
    const processFile = (file: File) => {
        if (file && file.type.startsWith('image/')) {
            const reader = new FileReader();
            reader.onloadend = () => {
                const base64 = (reader.result as string).split(',')[1];
                onFileProcessed({ file, data: base64, mimeType: file.type });
            };
            reader.readAsDataURL(file);
        }
    };
    return (
        <div className="w-full">
            <label className="block mb-2 font-semibold text-xs text-content-secondary uppercase tracking-wider">{label}</label>
            <label htmlFor={id} className={`relative flex flex-col items-center justify-center border-2 border-dashed border-border rounded-2xl cursor-pointer hover:border-brand-primary hover:bg-brand-primary/5 transition-all group overflow-hidden ${compact ? 'p-4 min-h-[140px]' : 'p-8 min-h-[220px]'}`}>
                <input id={id} type="file" onChange={(e) => e.target.files?.[0] && processFile(e.target.files[0])} accept="image/*" className="hidden" />
                {!uploadedFile ? (
                    <>
                        <UploadIcon className={`text-content-secondary group-hover:text-brand-primary transition-colors ${compact ? 'w-6 h-6 mb-2' : 'w-10 h-10 mb-4'}`} />
                        <p className={`text-center font-medium ${compact ? 'text-[10px]' : 'text-sm'}`}>Drop or Click</p>
                    </>
                ) : (
                    <div className="relative w-full h-full flex items-center justify-center">
                        <img src={URL.createObjectURL(uploadedFile.file)} className="max-h-full max-w-full rounded-lg object-contain shadow-xl" />
                        <div className="absolute inset-0 bg-background/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-all">
                             <p className="text-white text-xs font-bold bg-brand-primary px-3 py-1 rounded-full">Change</p>
                        </div>
                    </div>
                )}
            </label>
            {uploadedFile && <p className="mt-2 text-[10px] text-content-secondary truncate text-center">{uploadedFile.file.name}</p>}
        </div>
    );
};

