import { GoogleGenAI, Type, GenerateContentResponse, Part } from "@google/genai";
import { ProductInfo, AdAngle, Language, UploadedFile } from "../types";
import { brandArchetypes } from "../data/brandArchetypes";

const getGenAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateAdAngles = async (productInfo: ProductInfo, lang: Language): Promise<AdAngle[]> => {
  const ai = getGenAI();
  const model = "gemini-3-pro-preview";

  let brandContext = '';
  if (productInfo.brandArchetype && brandArchetypes[productInfo.brandArchetype]) {
    const archetype = brandArchetypes[productInfo.brandArchetype][lang];
    brandContext = `
    Brand Identity:
    - Archetype: ${archetype.name}
    - Tone: ${archetype.tone}
    `;
  }

  const langInstruction = lang === 'da' 
    ? "VIGTIGT: Alt indhold (titler og beskrivelser) SKAL genereres på DANSK." 
    : "IMPORTANT: All content must be generated in ENGLISH.";

  const prompt = `
    You are a world-class Direct Response Marketing Strategist. 
    ${langInstruction}

    Task: Generate 5 fresh, high-performing ad angles for:
    - Product: ${productInfo.name}
    - Audience: ${productInfo.audience}
    - USPs: ${productInfo.sellingPoints}
    - Goal: ${productInfo.goal}
    - Platform: ${productInfo.platform}
    ${brandContext}

    Instructions:
    1. Avoid boring angles. Focus on pattern interruption.
    2. Provide a title, a brief strategic description, and a visual prompt idea (visual prompt can be in English for better AI performance).

    Return result as JSON array.
  `;

  try {
    const response: GenerateContentResponse = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 16000 },
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              visual_prompt_idea: { type: Type.STRING },
            },
            required: ["title", "description", "visual_prompt_idea"],
          },
        },
      },
    });

    return JSON.parse(response.text.trim());
  } catch (error) {
    console.error("Error generating ad angles:", error);
    throw new Error(lang === 'da' ? "Kunne ikke generere vinkler." : "Failed to generate ad angles.");
  }
};

export const generateAdVisuals = async (
  angle: AdAngle,
  mainImage: UploadedFile,
  customPrompt: string,
  options: {
    numberOfImages: number;
    aspectRatio: string;
    useSuperRealism: boolean;
    styleReference?: UploadedFile;
    headline?: string;
    platform: string;
    textStyle: string;
    additionalAssets?: UploadedFile[];
  }
): Promise<string[]> => {
  const ai = getGenAI();
  const model = "gemini-3-pro-image-preview";

  const ratio = options.aspectRatio.includes('1:1') ? '1:1' : 
                options.aspectRatio.includes('9:16') ? '9:16' : 
                options.aspectRatio.includes('16:9') ? '16:9' : '1:1';

  try {
    const imagePromises = Array.from({ length: options.numberOfImages }, () => {
      let realismPart = options.useSuperRealism ? "Professional advertising photography, 8k, studio lighting, hyper-realistic textures." : "";
      let textOverlayPart = options.headline ? `Cleanly integrate this text: "${options.headline}". Typography style: ${options.textStyle}. Ensure readability.` : "";

      const fullPrompt = `
        TASK: High-end Advertising Creative Director.
        GOAL: Synthesize the provided image assets into a cohesive, high-converting ad for ${options.platform}.
        AD ANGLE STRATEGY: ${angle.title}
        PLACEMENT & ENVIRONMENT INSTRUCTIONS: ${customPrompt}

        TECHNICAL REQUIREMENTS:
        - Integrate all provided assets (Main Product + Additional Items) naturally into the scene.
        - Follow the placement instructions precisely (e.g., if asked to put a hat on a head, do it).
        - ${realismPart}
        - ${textOverlayPart}
        - Maintain consistent lighting and perspective across all assets.
      `;

      const parts: Part[] = [
          { inlineData: { data: mainImage.data, mimeType: mainImage.mimeType } }
      ];

      if (options.additionalAssets) {
          options.additionalAssets.forEach(asset => {
              parts.push({ inlineData: { data: asset.data, mimeType: asset.mimeType } });
          });
      }

      if (options.styleReference) {
          parts.push({ inlineData: { data: options.styleReference.data, mimeType: options.styleReference.mimeType } });
      }

      parts.push({ text: fullPrompt });

      return ai.models.generateContent({
        model: model,
        contents: { parts },
        config: { 
            imageConfig: { 
                aspectRatio: ratio as any, 
                imageSize: "1K" 
            } 
        },
      });
    });

    const responses = await Promise.all(imagePromises);
    const base64Images: string[] = [];
    for (const res of responses) {
      const part = res.candidates[0].content.parts.find(p => p.inlineData);
      if (part?.inlineData?.data) base64Images.push(part.inlineData.data);
    }
    return base64Images;
  } catch (error) {
    console.error("Visual generation failed:", error);
    throw new Error("Visual generation failed.");
  }
};

export const generateAdVideo = async (
  angle: AdAngle,
  baseImage: UploadedFile | null,
  customPrompt: string,
  options: { resolution: '720p' | '1080p', aspectRatio: '16:9' | '9:16' }
): Promise<string> => {
  const ai = getGenAI();
  const model = 'veo-3.1-fast-generate-preview';
  let operation = await ai.models.generateVideos({
    model: model,
    prompt: `Cinematic commercial: ${angle.title}. ${customPrompt}. Motion tracking product, professional lighting.`,
    image: baseImage ? { imageBytes: baseImage.data, mimeType: baseImage.mimeType } : undefined,
    config: { numberOfVideos: 1, resolution: options.resolution, aspectRatio: options.aspectRatio }
  });
  while (!operation.done) {
    await new Promise(resolve => setTimeout(resolve, 8000));
    operation = await ai.operations.getVideosOperation({ operation: operation });
  }
  const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
  const res = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
  const blob = await res.blob();
  return URL.createObjectURL(blob);
};

export const generateCaptions = async (productInfo: ProductInfo, angle: AdAngle, lang: Language): Promise<string[]> => {
  const ai = getGenAI();
  const model = "gemini-3-flash-preview";
  const langInstruction = lang === 'da' ? "Skriv teksterne på DANSK." : "Write captions in ENGLISH.";
  const prompt = `${langInstruction} Write 3 ad captions for ${productInfo.name}. Angle: ${angle.title}. Target: ${productInfo.audience}. Platform: ${productInfo.platform}. Rules: 1 short, 1 story, 1 benefit-driven.`;

  const response = await ai.models.generateContent({
    model: model,
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: { type: Type.ARRAY, items: { type: Type.STRING } },
    },
  });
  return JSON.parse(response.text.trim());
};

