const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('en');
  const t = TRANSLATIONS[lang];
  const [step, setStep] = useState<AppStep>(AppStep.LANDING);
  const [productInfo, setProductInfo] = useState<ProductInfo>({
    name: '', audience: '', sellingPoints: '', goal: CAMPAIGN_GOALS[0], brandArchetype: '', platform: 'Instagram'
  });
  const [adAngles, setAdAngles] = useState<AdAngle[]>([]);
  const [selectedAngle, setSelectedAngle] = useState<AdAngle | null>(null);
  const [generationMode, setGenerationMode] = useState<GenerationMode>('Image');

  // Multiple Assets
  const [mainAsset, setMainAsset] = useState<UploadedFile | null>(null);
  const [extraAsset1, setExtraAsset1] = useState<UploadedFile | null>(null);
  const [extraAsset2, setExtraAsset2] = useState<UploadedFile | null>(null);
  const [styleRef, setStyleRef] = useState<UploadedFile | null>(null);

  const [headlineText, setHeadlineText] = useState('');
  const [textStyle, setTextStyle] = useState('Classic');
  const [customPrompt, setCustomPrompt] = useState('');
  const [imageOptions, setImageOptions] = useState({ aspectRatio: 'Square (1:1)', count: 3 });
  const [videoOptions, setVideoOptions] = useState({ aspectRatio: 'Portrait (9:16)', resolution: '720p' });
  const [generatedImages, setGeneratedImages] = useState<string[]>([]);
  const [generatedVideoUrl, setGeneratedVideoUrl] = useState<string | null>(null);
  const [captions, setCaptions] = useState<string[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [loadingMessage, setLoadingMessage] = useState('');
  const [isGeneratingCaptions, setIsGeneratingCaptions] = useState(false);
  const [isZipping, setIsZipping] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [useSuperRealism, setUseSuperRealism] = useState(true);
  const [isApiKeyReady, setIsApiKeyReady] = useState(false);
  const [isCheckingApiKey, setIsCheckingApiKey] = useState(true);

  const videoMessageInterval = useRef<number | null>(null);

  useEffect(() => {
    const checkKey = async () => {
        if (window.aistudio && await window.aistudio.hasSelectedApiKey()) setIsApiKeyReady(true);
        setIsCheckingApiKey(false);
    };
    checkKey();
  }, []);

  const handleSelectKey = async () => {
    if (window.aistudio) {
        try { await window.aistudio.openSelectKey(); setIsApiKeyReady(true); } catch (e) {}
    }
  };

  const startVideoLoadingRotation = () => {
    const msgs = lang === 'da' ? VIDEO_LOADING_MESSAGES_DA : VIDEO_LOADING_MESSAGES_EN;
    let index = 0;
    setLoadingMessage(msgs[0]);
    videoMessageInterval.current = window.setInterval(() => {
        index = (index + 1) % msgs.length;
        setLoadingMessage(msgs[index]);
    }, 8000);
  };

  const handleDownloadAll = async () => {
    if (generatedImages.length === 0) return;
    setIsZipping(true);
    try {
      const zip = new JSZip();
      generatedImages.forEach((imgBase64, index) => {
        zip.file(`ad-variation-${index + 1}.png`, imgBase64, { base64: true });
      });
      const blob = await zip.generateAsync({ type: 'blob' });
      saveAs(blob, 'catalyst-ad-creatives.zip');
    } catch (err) {
      setError("Issue creating zip file.");
    } finally {
      setIsZipping(false);
    }
  };

  const startAngleGeneration = async () => {
    setIsLoading(true);
    setLoadingMessage(t.loading_angles);
    setError(null);
    try {
      const angles = await generateAdAngles(productInfo, lang);
      setAdAngles(angles);
      setStep(AppStep.GENERATE_ANGLES);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Error');
    } finally { setIsLoading(false); }
  };

  const startGeneration = async () => {
    if (generationMode === 'Image') {
      if (!selectedAngle || !mainAsset) {
          setError(lang === 'da' ? "Upload venligst mindst ét hovedbillede." : "Please upload at least the main image.");
          return;
      }
      setIsLoading(true);
      setLoadingMessage(t.loading_visuals);
      setError(null);
      try {
        const assets = [mainAsset];
        if (extraAsset1) assets.push(extraAsset1);
        if (extraAsset2) assets.push(extraAsset2);

        const imagesB64 = await generateAdVisuals(selectedAngle, mainAsset, customPrompt, {
          numberOfImages: imageOptions.count, 
          aspectRatio: imageOptions.aspectRatio, 
          useSuperRealism,
          styleReference: styleRef || undefined, 
          headline: headlineText, 
          platform: productInfo.platform, 
          textStyle,
          additionalAssets: [extraAsset1, extraAsset2].filter(Boolean) as UploadedFile[]
        });
        setGeneratedImages(imagesB64);
      } catch (err) { setError('Visual generation failed.'); } finally { setIsLoading(false); }
    } else {
      if (!selectedAngle) return;
      setIsLoading(true);
      startVideoLoadingRotation();
      setError(null);
      try {
        const videoUrl = await generateAdVideo(selectedAngle, mainAsset, customPrompt, {
          aspectRatio: videoOptions.aspectRatio.includes('9:16') ? '9:16' : '16:9',
          resolution: videoOptions.resolution as '720p' | '1080p'
        });
        setGeneratedVideoUrl(videoUrl);
      } catch (err) { setError('Video generation failed.'); } finally { if(videoMessageInterval.current) clearInterval(videoMessageInterval.current); setIsLoading(false); }
    }
  };

  const resetApp = () => {
    setStep(AppStep.LANDING);
    setSelectedAngle(null);
    setGeneratedImages([]);
    setGeneratedVideoUrl(null);
    setMainAsset(null);
    setExtraAsset1(null);
    setExtraAsset2(null);
    setStyleRef(null);
    setHeadlineText('');
    setCustomPrompt('');
