const VIDEO_LOADING_MESSAGES_EN = [
  "Initializing cinematic engine...",
  "Analyzing product geometry...",
  "Simulating studio environments...",
  "Optimizing for scroll-stopping impact...",
  "Polishing final frames..."
];

const VIDEO_LOADING_MESSAGES_DA = [
  "Initialiserer kinematisk motor...",
  "Analyserer produkt-geometri...",
  "Simulerer studiemiljøer...",
  "Optimerer til scroll-stop effekt...",
  "Polerer de sidste billedrammer..."
];

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('en');
  const t = TRANSLATIONS[lang];
  const [step, setStep] = useState<AppStep>(AppStep.LANDING);
  const [productInfo, setProductInfo] = useState<ProductInfo>({
    name: '', audience: '', sellingPoints: '', goal: CAMPAIGN_GOALS[0], brandArchetype: '', platform: 'Instagram'
  });
  const [adAngles, setAdAngles] = useState<AdAngle[]>([]);
  const [selectedAngle, setSelectedAngle] = useState<AdAngle | null>(null);
  const [generationMode, setGenerationMode] = useState<GenerationMode>('Image');

  // Multiple Assets
  const [mainAsset, setMainAsset] = useState<UploadedFile | null>(null);
  const [extraAsset1, setExtraAsset1] = useState<UploadedFile | null>(null);
  const [extraAsset2, setExtraAsset2] = useState<UploadedFile | null>(null);
  const [styleRef, setStyleRef] = useState<UploadedFile | null>(null);

  const [headlineText, setHeadlineText] = useState('');
  const [textStyle, setTextStyle] = useState('Classic');
  const [customPrompt, setCustomPrompt] = useState('');
  const [imageOptions, setImageOptions] = useState({ aspectRatio: 'Square (1:1)', count: 3 });
  const [videoOptions, setVideoOptions] = useState({ aspectRatio: 'Portrait (9:16)', resolution: '720p' });
  const [generatedImages, setGeneratedImages] = useState<string[]>([]);
  const [generatedVideoUrl, setGeneratedVideoUrl] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [loadingMessage, setLoadingMessage] = useState('');
  const [isZipping, setIsZipping] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [useSuperRealism, setUseSuperRealism] = useState(true);
  const [isApiKeyReady, setIsApiKeyReady] = useState(false);
  const [isCheckingApiKey, setIsCheckingApiKey] = useState(true);

  const videoMessageInterval = useRef<number | null>(null);

  useEffect(() => {
    const checkKey = async () => {
        if (window.aistudio && await window.aistudio.hasSelectedApiKey()) setIsApiKeyReady(true);
        setIsCheckingApiKey(false);
    };
    checkKey();
  }, []);

  const handleSelectKey = async () => {
    if (window.aistudio) {
        try { await window.aistudio.openSelectKey(); setIsApiKeyReady(true); } catch (e) {}
    }
  };

  const startVideoLoadingRotation = () => {
    const msgs = lang === 'da' ? VIDEO_LOADING_MESSAGES_DA : VIDEO_LOADING_MESSAGES_EN;
    let index = 0;
    setLoadingMessage(msgs[0]);
    videoMessageInterval.current = window.setInterval(() => {
        index = (index + 1) % msgs.length;
        setLoadingMessage(msgs[index]);
    }, 8000);
  };

  const handleDownloadAll = async () => {
    if (generatedImages.length === 0) return;
    setIsZipping(true);
    try {
      const zip = new JSZip();
      generatedImages.forEach((imgBase64, index) => {
        zip.file(`ad-variation-${index + 1}.png`, imgBase64, { base64: true });
      });
      const blob = await zip.generateAsync({ type: 'blob' });
      saveAs(blob, 'catalyst-ad-creatives.zip');
    } catch (err) {
      setError("Issue creating zip file.");
    } finally {
      setIsZipping(false);
    }
  };

  const startAngleGeneration = async () => {
    setIsLoading(true);
    setLoadingMessage(t.loading_angles);
    setError(null);
    try {
      const angles = await generateAdAngles(productInfo, lang);
      setAdAngles(angles);
      setStep(AppStep.GENERATE_ANGLES);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Error');
    } finally { setIsLoading(false); }
  };

  const startGeneration = async () => {
    if (generationMode === 'Image') {
      if (!selectedAngle || !mainAsset) {
          setError(lang === 'da' ? "Upload venligst mindst ét hovedbillede." : "Please upload at least the main image.");
          return;
      }
      setIsLoading(true);
      setLoadingMessage(t.loading_visuals);
      setError(null);
      try {
        const imagesB64 = await generateAdVisuals(selectedAngle, mainAsset, customPrompt, {
          numberOfImages: imageOptions.count, 
          aspectRatio: imageOptions.aspectRatio, 
          useSuperRealism,
          styleReference: styleRef || undefined, 
          headline: headlineText, 
          platform: productInfo.platform, 
          textStyle,
          additionalAssets: [extraAsset1, extraAsset2].filter(Boolean) as UploadedFile[]
        });
        setGeneratedImages(imagesB64);
      } catch (err) { setError('Visual generation failed.'); } finally { setIsLoading(false); }
    } else {
      if (!selectedAngle) return;
      setIsLoading(true);
      startVideoLoadingRotation();
      setError(null);
      try {
        const videoUrl = await generateAdVideo(selectedAngle, mainAsset, customPrompt, {
          aspectRatio: videoOptions.aspectRatio.includes('9:16') ? '9:16' : '16:9',
          resolution: videoOptions.resolution as '720p' | '1080p'
        });
        setGeneratedVideoUrl(videoUrl);
      } catch (err) { setError('Video generation failed.'); } finally { if(videoMessageInterval.current) clearInterval(videoMessageInterval.current); setIsLoading(false); }
    }
  };

  const animateGeneratedImage = async (base64: string) => {
    setGenerationMode('Video');
    setGeneratedImages([]);
    setGeneratedVideoUrl(null);

    // Convert base64 back to a "virtual" file for the pipeline
    const byteString = atob(base64);
    const ab = new ArrayBuffer(byteString.length);
    const ia = new Uint8Array(ab);
    for (let i = 0; i < byteString.length; i++) ia[i] = byteString.charCodeAt(i);
    const blob = new Blob([ab], { type: 'image/png' });
    const virtualFile = new File([blob], "ai-generated-asset.png", { type: 'image/png' });

    setMainAsset({
        file: virtualFile,
        data: base64,
        mimeType: 'image/png'
    });

    setStep(AppStep.GENERATE_VISUALS);
    // Auto-trigger video generation? Maybe let the user confirm prompt first
  };

  const resetApp = () => {
    setStep(AppStep.LANDING);
    setSelectedAngle(null);
    setGeneratedImages([]);
    setGeneratedVideoUrl(null);
    setMainAsset(null);
    setExtraAsset1(null);
    setExtraAsset2(null);
    setStyleRef(null);
    setHeadlineText('');
    setCustomPrompt('');
  };

  const renderLanding = () => (
    <div className="text-center max-w-4xl mx-auto py-12">
      <div className="inline-block p-6 bg-brand-primary/10 rounded-3xl mb-8 border border-brand-primary/20">
        <SparklesIcon className="w-16 h-16 text-brand-primary" />
      </div>
      <h1 className="text-5xl md:text-7xl font-bold tracking-tight text-content-primary mb-6">{t.landing_title}</h1>
      <p className="text-xl md:text-2xl text-content-secondary mb-12 max-w-2xl mx-auto leading-relaxed">{t.landing_subtitle}</p>
      <button onClick={() => setStep(AppStep.DEFINE_PRODUCT)} className="bg-gradient-to-r from-brand-primary to-brand-secondary text-white font-bold py-5 px-12 rounded-full text-xl hover:scale-105 transition-all shadow-[0_0_40px_rgba(129,140,248,0.3)]">
        {t.btn_start}
      </button>
    </div>
  );

  const renderDefineProduct = () => (
    <div className="w-full max-w-4xl mx-auto">
      <div className="bg-surface border border-border p-8 md:p-12 rounded-[2.5rem] shadow-2xl">
        <h2 className="text-3xl font-bold mb-8 text-center uppercase tracking-widest">{t.define_title}</h2>
        <div className="grid md:grid-cols-2 gap-x-8 gap-y-10">
            <div className="md:col-span-2 space-y-2">
                <div className="flex justify-between items-end">
                    <label className="font-bold block text-brand-primary text-sm uppercase tracking-wide">{t.label_name}</label>
                    <span className="text-[10px] text-content-secondary italic">{t.desc_name}</span>
                </div>
                <input type="text" value={productInfo.name} placeholder={t.placeholder_name} onChange={(e) => setProductInfo({...productInfo, name: e.target.value})} className="w-full p-4 bg-background border border-border rounded-xl focus:ring-2 focus:ring-brand-primary transition-all outline-none" />
            </div>
            <div className="space-y-2">
                <div className="flex flex-col">
                    <label className="font-bold text-brand-primary text-sm uppercase tracking-wide">{t.label_audience}</label>
                    <span className="text-[10px] text-content-secondary mb-1">{t.desc_audience}</span>
                </div>
                <input type="text" value={productInfo.audience} placeholder={t.placeholder_audience} onChange={(e) => setProductInfo({...productInfo, audience: e.target.value})} className="w-full p-4 bg-background border border-border rounded-xl focus:ring-2 focus:ring-brand-primary transition-all outline-none" />
            </div>
            <div className="space-y-2">
                <div className="flex flex-col">
                    <label className="font-bold text-brand-primary text-sm uppercase tracking-wide">{t.label_selling_points}</label>
                    <span className="text-[10px] text-content-secondary mb-1">{t.desc_points}</span>
                </div>
                <input value={productInfo.sellingPoints} placeholder={t.placeholder_points} onChange={(e) => setProductInfo({...productInfo, sellingPoints: e.target.value})} className="w-full p-4 bg-background border border-border rounded-xl focus:ring-2 focus:ring-brand-primary transition-all outline-none" />
            </div>
            <div className="space-y-2">
                <div className="flex flex-col">
                    <label className="font-bold text-brand-primary text-sm uppercase tracking-wide">{t.label_goal}</label>
                    <span className="text-[10px] text-content-secondary mb-1">{t.desc_goal}</span>
                </div>
                <select value={productInfo.goal} onChange={(e) => setProductInfo({...productInfo, goal: e.target.value})} className="w-full p-4 bg-background border border-border rounded-xl appearance-none outline-none focus:ring-2 focus:ring-brand-primary cursor-pointer">
                    {CAMPAIGN_GOALS.map(g => <option key={g} value={g}>{g}</option>)}
                </select>
            </div>
            <div className="space-y-2">
                <div className="flex flex-col">
                    <label className="font-bold text-brand-primary text-sm uppercase tracking-wide">{t.label_platform}</label>
                    <span className="text-[10px] text-content-secondary mb-1">{t.desc_platform}</span>
                </div>
                <select value={productInfo.platform} onChange={(e) => setProductInfo({...productInfo, platform: e.target.value})} className="w-full p-4 bg-background border border-border rounded-xl appearance-none outline-none focus:ring-2 focus:ring-brand-primary cursor-pointer">
                    {['Instagram (Meta 2026)', 'TikTok (UGC High-End)', 'Facebook (Direct Response)'].map(p => <option key={p} value={p}>{p}</option>)}
                </select>
            </div>
            <div className="md:col-span-2 space-y-2">
                <div className="flex flex-col">
                    <label className="font-bold text-brand-primary text-sm uppercase tracking-wide">{t.label_archetype}</label>
                    <span className="text-[10px] text-content-secondary mb-1">{t.desc_archetype}</span>
                </div>
                <select value={productInfo.brandArchetype} onChange={(e) => setProductInfo({...productInfo, brandArchetype: e.target.value})} className="w-full p-4 bg-background border border-border rounded-xl appearance-none outline-none focus:ring-2 focus:ring-brand-primary cursor-pointer">
                    <option value="">-- No Archetype (Standard Mix) --</option>
                    {Object.entries(brandArchetypes).map(([key, arch]) => (
                        <option key={key} value={key}>{arch[lang].name} — {arch[lang].vibe}</option>
                    ))}
                </select>
            </div>
            <div className="md:col-span-2 mt-12">
                <button onClick={startAngleGeneration} disabled={!productInfo.name} className="w-full bg-gradient-to-r from-brand-primary to-brand-secondary text-white font-bold py-6 px-6 rounded-2xl text-2xl transition-all disabled:opacity-30 hover:shadow-[0_0_50px_rgba(129,140,248,0.4)] hover:scale-[1.01] active:scale-[0.99]">
                    {t.btn_brainstorm}
                </button>
            </div>
        </div>
      </div>
    </div>
  );

  const renderGenerateAngles = () => (
    <div className="w-full max-w-6xl mx-auto">
      {isLoading ? <Loader message={loadingMessage} /> : (
        <>
        <div className="text-center mb-12">
            <h2 className="text-4xl font-bold text-content-primary mb-3">{t.angle_title}</h2>
            <p className="text-content-secondary text-lg">{t.angle_subtitle}</p>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {adAngles.map((angle, index) => (
            <div key={index} onClick={() => {setSelectedAngle(angle); setCustomPrompt(angle.visual_prompt_idea);}} className={`p-8 rounded-3xl cursor-pointer border-2 bg-surface transition-all ${selectedAngle?.title === angle.title ? 'border-brand-primary ring-1 ring-brand-primary' : 'border-border'} hover:border-brand-primary/50`}>
              <h3 className="text-2xl font-bold mb-4">{angle.title}</h3>
              <p className="text-content-secondary">{angle.description}</p>
            </div>
          ))}
        </div>
        <div className="mt-16 flex justify-center space-x-6">
            <button onClick={() => setStep(AppStep.DEFINE_PRODUCT)} className="px-10 py-4 font-bold text-lg text-content-secondary hover:text-content-primary transition-colors">{t.btn_back}</button>
            {selectedAngle && <button onClick={() => setStep(AppStep.GENERATE_VISUALS)} className="bg-brand-primary text-white font-bold py-4 px-12 rounded-full text-xl shadow-xl hover:scale-105 transition-all">{t.btn_next_production}</button>}
        </div>
        </>
      )}
    </div>
  );

  const renderGenerateVisuals = () => {
    if (isLoading) return <Loader message={loadingMessage} />;

    if (generatedImages.length > 0 || generatedVideoUrl) {
      return (
        <div className="text-center space-y-12">
            <div>
                <h2 className="text-4xl font-bold mb-4">{t.production_complete}</h2>
                <p className="text-content-secondary text-lg">{t.production_subtitle}</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 max-w-7xl mx-auto">
              {generatedImages.map((img, i) => (
                  <div key={i} className="bg-surface p-4 rounded-[2.5rem] border border-border shadow-2xl space-y-4 group">
                    <div className="relative aspect-square overflow-hidden rounded-2xl">
                        <img src={`data:image/png;base64,${img}`} className="w-full h-full object-cover transition-transform group-hover:scale-105" />
                        <div className="absolute inset-0 bg-background/60 opacity-0 group-hover:opacity-100 flex items-center justify-center gap-4 transition-all">
                            <a href={`data:image/png;base64,${img}`} download={`catalyst-ad-${i+1}.png`} className="p-3 bg-brand-primary rounded-full hover:scale-110 transition-transform shadow-xl">
                                <DownloadIcon className="w-6 h-6 text-white" />
                            </a>
                        </div>
                    </div>
                    <button onClick={() => animateGeneratedImage(img)} className="w-full py-3 px-4 bg-indigo-900/30 border border-brand-primary/30 text-brand-primary font-bold rounded-xl hover:bg-brand-primary hover:text-white transition-all flex items-center justify-center gap-2">
                        <VideoIcon className="w-5 h-5" /> {t.btn_animate}
                    </button>
                  </div>
              ))}
            </div>

            {generatedVideoUrl && (
                <div className="max-w-2xl mx-auto bg-surface p-6 rounded-[3rem] border border-border shadow-2xl">
                    <video src={generatedVideoUrl} controls autoPlay loop className="w-full h-auto rounded-2xl" />
                    <div className="mt-6 flex justify-center">
                         <a href={generatedVideoUrl} download="catalyst-video.mp4" className="bg-brand-secondary text-white font-bold py-3 px-8 rounded-full flex items-center shadow-xl">
                            <DownloadIcon className="w-5 h-5 mr-2" /> {t.btn_download_video}
                         </a>
                    </div>
                </div>
            )}

            <div className="flex flex-wrap justify-center gap-6 pt-8">
               <button onClick={() => { setGeneratedImages([]); setGeneratedVideoUrl(null); }} className="bg-surface border border-border text-content-primary font-bold py-4 px-10 rounded-full hover:bg-border transition-all">
                   {t.btn_refine_production}
               </button>
               {generatedImages.length > 0 && (
                   <button onClick={handleDownloadAll} disabled={isZipping} className="bg-brand-secondary text-white font-bold py-4 px-10 rounded-full flex items-center shadow-xl">
                       {isZipping ? 'Zipping...' : t.btn_download_zip}
                   </button>
               )}
               <button onClick={resetApp} className="bg-brand-primary text-white font-bold py-4 px-10 rounded-full shadow-xl hover:scale-105 transition-all">
                   {t.btn_new_campaign}
               </button>
            </div>
        </div>
      );
    }

    return (
      <div className="w-full max-w-7xl mx-auto space-y-12">
        <div className="flex justify-center">
            <div className="bg-surface p-1.5 rounded-full flex border border-border shadow-2xl">
                <button onClick={() => setGenerationMode('Image')} className={`px-12 py-3 rounded-full font-bold transition-all ${generationMode === 'Image' ? 'bg-brand-primary text-white shadow-lg' : 'text-content-secondary hover:text-content-primary'}`}>{t.mode_static}</button>
                <button onClick={() => setGenerationMode('Video')} className={`px-12 py-3 rounded-full font-bold transition-all ${generationMode === 'Video' ? 'bg-brand-primary text-white shadow-lg' : 'text-content-secondary hover:text-content-primary'}`}>{t.mode_video}</button>
            </div>
        </div>
        <div className="grid lg:grid-cols-3 gap-8 items-stretch">
            {/* COLUMN 1: ASSETS */}
            <div className="bg-surface p-8 rounded-[2.5rem] border border-border space-y-6">
                <h3 className="font-bold text-lg mb-2">{lang === 'da' ? 'Dine Aktiver' : 'Your Assets'}</h3>
                <div className="grid grid-cols-2 gap-4">
                    <div className="col-span-2">
                         <FileUploader id="main" label={t.upload_main} uploadedFile={mainAsset} onFileProcessed={setMainAsset} onError={setError} />
                    </div>
                    <FileUploader id="extra1" label={t.upload_extra1} uploadedFile={extraAsset1} onFileProcessed={setExtraAsset1} onError={setError} compact />
                    <FileUploader id="extra2" label={t.upload_extra2} uploadedFile={extraAsset2} onFileProcessed={setExtraAsset2} onError={setError} compact />
                </div>
                <FileUploader id="style" label={t.upload_style} uploadedFile={styleRef} onFileProcessed={setStyleRef} onError={setError} compact />
            </div>

            {/* COLUMN 2: CONTEXT */}
            <div className="bg-surface p-8 rounded-[2.5rem] border border-border space-y-6">
                <h3 className="font-bold text-lg mb-2">{lang === 'da' ? 'Strategisk Kontekst' : 'Strategic Context'}</h3>
                <div>
                    <label className="block mb-2 font-semibold text-sm text-content-secondary">{t.label_headline}</label>
                    <input value={headlineText} placeholder={t.placeholder_headline} onChange={(e) => setHeadlineText(e.target.value)} className="w-full p-4 bg-background border border-border rounded-xl focus:ring-2 focus:ring-brand-primary" />
                </div>
                <div>
                    <label className="block mb-2 font-semibold text-sm text-content-secondary">{t.label_directives}</label>
                    <textarea value={customPrompt} placeholder={t.placeholder_directives} onChange={(e) => setCustomPrompt(e.target.value)} rows={8} className="w-full p-4 bg-background border border-border rounded-xl resize-none focus:ring-2 focus:ring-brand-primary" />
                </div>
            </div>

            {/* COLUMN 3: SETTINGS & PRODUCE */}
            <div className="bg-surface p-8 rounded-[2.5rem] border border-border flex flex-col justify-between">
                <div className="space-y-6">
                    <h3 className="font-bold text-lg mb-2">{lang === 'da' ? 'Indstillinger' : 'Production Settings'}</h3>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block mb-2 font-semibold text-xs text-content-secondary">{t.label_ratio}</label>
                            <select value={imageOptions.aspectRatio} onChange={(e) => setImageOptions({...imageOptions, aspectRatio: e.target.value})} className="w-full p-3 bg-background border border-border rounded-xl text-sm">
                                <option>Square (1:1)</option>
                                <option>Portrait (9:16)</option>
                                <option>Landscape (16:9)</option>
                            </select>
                        </div>
                        <div>
                            <label className="block mb-2 font-semibold text-xs text-content-secondary">{t.label_variations}</label>
                            <select value={imageOptions.count} onChange={(e) => setImageOptions({...imageOptions, count: parseInt(e.target.value)})} className="w-full p-3 bg-background border border-border rounded-xl text-sm">
                                {[1, 2, 3, 4].map(n => <option key={n} value={n}>{n}</option>)}
                            </select>
                        </div>
                    </div>
                    <div className="p-4 bg-background border border-border rounded-2xl flex items-center justify-between">
                        <label className="font-bold text-sm text-content-primary">{t.label_realism}</label>
                        <label className="relative inline-flex items-center cursor-pointer">
                            <input type="checkbox" checked={useSuperRealism} onChange={() => setUseSuperRealism(!useSuperRealism)} className="sr-only peer" />
                            <div className="w-11 h-6 bg-border rounded-full peer peer-checked:bg-brand-primary after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:after:translate-x-full"></div>
                        </label>
                    </div>
                </div>
                <div className="space-y-4">
                    {error && <p className="text-red-400 text-sm text-center font-bold">{error}</p>}
                    <button onClick={startGeneration} className="w-full bg-gradient-to-r from-brand-primary to-brand-secondary text-white font-bold py-5 rounded-2xl text-xl shadow-2xl hover:scale-[1.02] transition-all flex items-center justify-center">
                        <SparklesIcon className="w-6 h-6 mr-3" /> {t.btn_produce}
                    </button>
                    <button onClick={() => setStep(AppStep.GENERATE_ANGLES)} className="w-full text-content-secondary hover:text-content-primary font-bold py-2 transition-all">{t.btn_back}</button>
                </div>
            </div>
        </div>
      </div>
    );
  };

  if (isCheckingApiKey) return <div className="min-h-screen flex items-center justify-center bg-background"><Loader message="Loading Catalyst..." /></div>;

  if (!isApiKeyReady) {
    return (
        <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-background">
            <div className="p-12 bg-surface border border-border rounded-3xl shadow-2xl max-w-lg text-center">
                <VideoIcon className="w-20 h-20 text-brand-primary mx-auto mb-8" />
                <h1 className="text-4xl font-bold mb-6">{t.activation_title}</h1>
                <p className="text-content-secondary mb-10 text-lg leading-relaxed">{t.activation_subtitle}</p>
                <button onClick={handleSelectKey} className="w-full bg-gradient-to-r from-brand-primary to-brand-secondary text-white font-bold py-5 px-8 rounded-2xl text-xl hover:shadow-2xl transition-all">{t.btn_select_key}</button>
            </div>
        </div>
    );
  }

  const renderContent = () => {
    switch (step) {
      case AppStep.LANDING: return renderLanding();
      case AppStep.DEFINE_PRODUCT: return renderDefineProduct();
      case AppStep.GENERATE_ANGLES: return renderGenerateAngles();
      case AppStep.GENERATE_VISUALS: return renderGenerateVisuals();
      default: return renderLanding();
    }
  };

  return (
    <div className="min-h-screen w-full flex flex-col items-center p-4 md:p-12 bg-background text-content-primary relative overflow-x-hidden">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-brand-primary/10 rounded-full blur-[120px] pointer-events-none"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-brand-secondary/10 rounded-full blur-[120px] pointer-events-none"></div>

        <div className="absolute top-8 right-8 z-50">
          <div className="bg-surface/50 backdrop-blur-md border border-border p-1.5 rounded-full flex shadow-2xl">
            <button onClick={() => setLang('en')} className={`px-5 py-2 rounded-full text-xs font-bold transition-all ${lang === 'en' ? 'bg-brand-primary text-white shadow-lg' : 'text-content-secondary hover:text-content-primary'}`}>EN</button>
            <button onClick={() => setLang('da')} className={`px-5 py-2 rounded-full text-xs font-bold transition-all ${lang === 'da' ? 'bg-brand-primary text-white shadow-lg' : 'text-content-secondary hover:text-content-primary'}`}>DA</button>
          </div>
        </div>

        <div className="relative z-10 w-full flex flex-col items-center">
            {step !== AppStep.LANDING && (
                <header className="w-full max-w-6xl mx-auto mb-16 text-center space-y-8">
                    <h1 className="text-4xl font-bold cursor-pointer tracking-tight" onClick={resetApp}>
                        Creative Catalyst <span className="text-brand-primary">Studio</span>
                    </h1>
                    <Stepper currentStepEnum={step} onStepClick={(s) => setStep(s)} />
                </header>
            )}
            <main className="w-full">{renderContent()}</main>
        </div>
    </div>
  );
};

const Stepper: React.FC<{ currentStepEnum: AppStep, onStepClick: (s: AppStep) => void }> = ({ currentStepEnum, onStepClick }) => {
    const steps = [AppStep.DEFINE_PRODUCT, AppStep.GENERATE_ANGLES, AppStep.GENERATE_VISUALS];
    if (!steps.includes(currentStepEnum)) return null;
    const labels = ["Define", "Angle", "Visuals"];
    return (
        <nav className="flex items-center justify-center space-x-4 md:space-x-12">
            {steps.map((s, i) => {
                const isActive = currentStepEnum === s;
                const isCompleted = steps.indexOf(currentStepEnum) > i;
                return (
                    <div key={i} className={`flex items-center text-sm font-semibold transition-all ${isActive ? 'text-brand-primary' : isCompleted ? 'text-indigo-300' : 'text-content-secondary'}`}>
                        <span className={`h-10 w-10 flex items-center justify-center rounded-full mr-3 border-2 transition-all ${isActive ? 'bg-brand-primary text-white border-brand-primary shadow-[0_0_20px_rgba(129,140,248,0.4)]' : isCompleted ? 'bg-indigo-900/30 border-brand-primary text-brand-primary' : 'bg-surface border-border'}`}>{i+1}</span>
                        <span className="hidden md:inline text-base">{labels[i]}</span>
                    </div>
                );
            })}
        </nav>
    );
};

const FileUploader: React.FC<{ id: string, label: string, uploadedFile: UploadedFile | null, onFileProcessed: (f: UploadedFile) => void, onError: (m: string) => void, compact?: boolean }> = ({ id, label, uploadedFile, onFileProcessed, onError, compact }) => {
    const processFile = (file: File) => {
        if (file && file.type.startsWith('image/')) {
            const reader = new FileReader();
            reader.onloadend = () => {
                const base64 = (reader.result as string).split(',')[1];
                onFileProcessed({ file, data: base64, mimeType: file.type });
            };
            reader.readAsDataURL(file);
        }
    };
    return (
        <div className="w-full">
            <label className="block mb-2 font-semibold text-xs text-content-secondary uppercase tracking-wider">{label}</label>
            <label htmlFor={id} className={`relative flex flex-col items-center justify-center border-2 border-dashed border-border rounded-2xl cursor-pointer hover:border-brand-primary hover:bg-brand-primary/5 transition-all group overflow-hidden ${compact ? 'p-4 min-h-[140px]' : 'p-8 min-h-[220px]'}`}>
                <input id={id} type="file" onChange={(e) => e.target.files?.[0] && processFile(e.target.files[0])} accept="image/*" className="hidden" />
                {!uploadedFile ? (
                    <>
                        <UploadIcon className={`text-content-secondary group-hover:text-brand-primary transition-colors ${compact ? 'w-6 h-6 mb-2' : 'w-10 h-10 mb-4'}`} />
                        <p className={`text-center font-medium ${compact ? 'text-[10px]' : 'text-sm'}`}>Drop or Click</p>
                    </>
                ) : (
                    <div className="relative w-full h-full flex items-center justify-center">
                        <img src={URL.createObjectURL(uploadedFile.file)} className="max-h-full max-w-full rounded-lg object-contain shadow-xl" />
                        <div className="absolute inset-0 bg-background/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-all">
                             <p className="text-white text-xs font-bold bg-brand-primary px-3 py-1 rounded-full">Change</p>
                        </div>
                    </div>
                )}
            </label>
            {uploadedFile && <p className="mt-2 text-[10px] text-content-secondary truncate text-center">{uploadedFile.file.name}</p>}
        </div>
    );
};

export default App;

