const VIDEO_LOADING_MESSAGES_DA = [
  "Initialiserer kinematisk motor...",
  "Analyserer produkt-geometri...",
  "Simulerer studiemiljøer...",
  "Optimerer til scroll-stop effekt...",
  "Polerer de sidste billedrammer..."
