      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[120%] h-[120%] bg-brand-primary/5 rounded-full blur-[160px] pointer-events-none"></div>

      {/* Delefin Pink Dolphin Logo */}
      <div className="relative z-10 w-32 h-32 md:w-40 md:h-40 mb-12 animate-float">
        <PinkDolphinLogo />
      </div>

      {/* Main Content */}
      <div className="relative z-10 text-center space-y-8 max-w-5xl mx-auto">
        <h1 className="text-6xl md:text-9xl font-bold tracking-tight text-content-primary leading-[1] drop-shadow-2xl">
          {t.landing_title}
        </h1>
        <p className="text-xl md:text-3xl text-content-secondary max-w-3xl mx-auto leading-relaxed font-light italic">
