        </p>

        <div className="pt-12">
          <button 
            onClick={() => setStep(AppStep.DEFINE_PRODUCT)} 
            className="group relative overflow-hidden bg-gradient-to-r from-brand-primary to-brand-secondary text-white font-bold py-6 px-16 rounded-full text-2xl hover:scale-105 transition-all shadow-[0_20px_60px_-15px_rgba(129,140,248,0.5)] active:scale-95"
          >
            <span className="relative z-10">{t.btn_start}</span>
            <div className="absolute inset-0 bg-white/20 translate-y-full group-hover:translate-y-0 transition-transform duration-300"></div>
          </button>
        </div>
      </div>

      {/* Background accents */}
      <div className="absolute top-0 right-0 w-64 h-64 bg-brand-secondary/10 rounded-full blur-[100px] -mr-32 -mt-32"></div>
      <div className="absolute bottom-0 left-0 w-64 h-64 bg-brand-primary/10 rounded-full blur-[100px] -ml-32 -mb-32"></div>
    </div>
  );

  const renderDefineProduct = () => (
    <div className="w-full max-w-4xl mx-auto px-4 md:px-0">
      <div className="bg-surface border border-border p-6 md:p-12 rounded-[2rem] md:rounded-[2.5rem] shadow-2xl">
        <h2 className="text-2xl md:text-3xl font-bold mb-8 text-center uppercase tracking-widest text-brand-primary">{t.define_title}</h2>
        <div className="grid md:grid-cols-2 gap-x-8 gap-y-10">
            <div className="md:col-span-2 space-y-2">
                <div className="flex justify-between items-end">
                    <label className="font-bold block text-brand-primary text-xs md:text-sm uppercase tracking-wide">{t.label_name}</label>
                    <span className="text-[10px] text-content-secondary italic hidden md:inline">{t.desc_name}</span>
                </div>
                <input type="text" value={productInfo.name} placeholder={t.placeholder_name} onChange={(e) => setProductInfo({...productInfo, name: e.target.value})} className="w-full p-4 bg-background border border-border rounded-xl focus:ring-2 focus:ring-brand-primary transition-all outline-none" />
            </div>
            <div className="space-y-2">
                <div className="flex flex-col">
                    <label className="font-bold text-brand-primary text-xs md:text-sm uppercase tracking-wide">{t.label_audience}</label>
                    <span className="text-[10px] text-content-secondary mb-1">{t.desc_audience}</span>
                </div>
                <input type="text" value={productInfo.audience} placeholder={t.placeholder_audience} onChange={(e) => setProductInfo({...productInfo, audience: e.target.value})} className="w-full p-4 bg-background border border-border rounded-xl focus:ring-2 focus:ring-brand-primary transition-all outline-none" />
            </div>
            <div className="space-y-2">
