                    {CAMPAIGN_GOALS.map(g => <option key={g} value={g}>{g}</option>)}
                </select>
            </div>
            <div className="space-y-2">
                <div className="flex flex-col">
                    <label className="font-bold text-brand-primary text-xs md:text-sm uppercase tracking-wide">{t.label_platform}</label>
                    <span className="text-[10px] text-content-secondary mb-1">{t.desc_platform}</span>
                </div>
                <select value={productInfo.platform} onChange={(e) => setProductInfo({...productInfo, platform: e.target.value})} className="w-full p-4 bg-background border border-border rounded-xl appearance-none outline-none focus:ring-2 focus:ring-brand-primary cursor-pointer">
                    {['Instagram (Meta 2026)', 'TikTok (UGC High-End)', 'Facebook (Direct Response)'].map(p => <option key={p} value={p}>{p}</option>)}
                </select>
            </div>
            <div className="md:col-span-2 space-y-2">
                <div className="flex flex-col">
                    <label className="font-bold text-brand-primary text-xs md:text-sm uppercase tracking-wide">{t.label_archetype}</label>
                    <span className="text-[10px] text-content-secondary mb-1">{t.desc_archetype}</span>
                </div>
                <select value={productInfo.brandArchetype} onChange={(e) => setProductInfo({...productInfo, brandArchetype: e.target.value})} className="w-full p-4 bg-background border border-border rounded-xl appearance-none outline-none focus:ring-2 focus:ring-brand-primary cursor-pointer">
                    <option value="">-- No Archetype (Standard Mix) --</option>
                    {Object.entries(brandArchetypes).map(([key, arch]) => (
                        <option key={key} value={key}>{arch[lang].name} — {arch[lang].vibe}</option>
