            </div>
            <div className="md:col-span-2 mt-12">
                <button onClick={startAngleGeneration} disabled={!productInfo.name} className="w-full bg-gradient-to-r from-brand-primary to-brand-secondary text-white font-bold py-6 px-6 rounded-2xl text-xl md:text-2xl transition-all disabled:opacity-30 hover:shadow-[0_0_50px_rgba(129,140,248,0.4)] hover:scale-[1.01] active:scale-[0.99]">
                    {t.btn_brainstorm}
                </button>
