            <div key={index} onClick={() => {setSelectedAngle(angle); setCustomPrompt(angle.visual_prompt_idea);}} className={`p-6 md:p-8 rounded-[2rem] cursor-pointer border-2 bg-surface transition-all ${selectedAngle?.title === angle.title ? 'border-brand-primary ring-1 ring-brand-primary shadow-xl scale-[1.02]' : 'border-border'} hover:border-brand-primary/50`}>
