        <div className="mt-16 flex flex-col md:flex-row items-center justify-center space-y-4 md:space-y-0 md:space-x-6">
            <button onClick={() => setStep(AppStep.DEFINE_PRODUCT)} className="px-10 py-4 font-bold text-lg text-content-secondary hover:text-content-primary transition-colors">{t.btn_back}</button>
