const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('en');
  const t = TRANSLATIONS[lang];
  const [step, setStep] = useState<AppStep>(AppStep.LANDING);
  const [productInfo, setProductInfo] = useState<ProductInfo>({
    name: '', audience: '', sellingPoints: '', goal: CAMPAIGN_GOALS[0], brandArchetype: '', platform: 'Instagram'
  });
  const [adAngles, setAdAngles] = useState<AdAngle[]>([]);
  const [selectedAngle, setSelectedAngle] = useState<AdAngle | null>(null);
  const [generationMode, setGenerationMode] = useState<GenerationMode>('Image');

  const [mainAsset, setMainAsset] = useState<UploadedFile | null>(null);
  const [extraAsset1, setExtraAsset1] = useState<UploadedFile | null>(null);
  const [extraAsset2, setExtraAsset2] = useState<UploadedFile | null>(null);
  const [styleRef, setStyleRef] = useState<UploadedFile | null>(null);

  const [headlineText, setHeadlineText] = useState('');
  const [textStyle, setTextStyle] = useState('Classic');
  const [customPrompt, setCustomPrompt] = useState('');
  const [imageOptions, setImageOptions] = useState({ aspectRatio: 'Square (1:1)', count: 3 });
  const [videoOptions, setVideoOptions] = useState({ aspectRatio: 'Portrait (9:16)', resolution: '720p' });
  const [generatedImages, setGeneratedImages] = useState<string[]>([]);
  const [generatedVideoUrl, setGeneratedVideoUrl] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [loadingMessage, setLoadingMessage] = useState('');
  const [isZipping, setIsZipping] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [useSuperRealism, setUseSuperRealism] = useState(true);
  const [isApiKeyReady, setIsApiKeyReady] = useState(false);
  const [isCheckingApiKey, setIsCheckingApiKey] = useState(true);

  const videoMessageInterval = useRef<number | null>(null);

  useEffect(() => {
    const checkKey = async () => {
        if (window.aistudio && await window.aistudio.hasSelectedApiKey()) setIsApiKeyReady(true);
        setIsCheckingApiKey(false);
    };
    checkKey();
  }, []);

  const handleSelectKey = async () => {
    if (window.aistudio) {
        try { await window.aistudio.openSelectKey(); setIsApiKeyReady(true); } catch (e) {}
    }
  };

  const startVideoLoadingRotation = () => {
    const msgs = lang === 'da' ? ["Initialiserer...", "Analyserer...", "Skaber magi..."] : ["Initializing...", "Analyzing...", "Creating magic..."];
    let index = 0;
    setLoadingMessage(msgs[0]);
    videoMessageInterval.current = window.setInterval(() => {
        index = (index + 1) % msgs.length;
        setLoadingMessage(msgs[index]);
    }, 8000);
  };

  const handleDownloadAll = async () => {
    if (generatedImages.length === 0) return;
    setIsZipping(true);
    try {
      const zip = new JSZip();
      generatedImages.forEach((imgBase64, index) => {
        zip.file(`ad-${index + 1}.png`, imgBase64, { base64: true });
      });
      const blob = await zip.generateAsync({ type: 'blob' });
      saveAs(blob, 'ugc-creatives.zip');
    } catch (err) {
      setError("Download failed.");
    } finally {
      setIsZipping(false);
    }
  };

  const startAngleGeneration = async () => {
    setIsLoading(true);
    setLoadingMessage("🧠 Brainstorming strategy...");
    setError(null);
    try {
      const angles = await generateAdAngles(productInfo, lang);
      setAdAngles(angles);
      setStep(AppStep.GENERATE_ANGLES);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Error');
    } finally { setIsLoading(false); }
  };

  const startGeneration = async () => {
    if (generationMode === 'Image') {
      if (!selectedAngle || !mainAsset) {
          setError("Upload main image first! 📸");
          return;
      }
      setIsLoading(true);
      setLoadingMessage("🎨 Painting assets...");
      setError(null);
      try {
        const imagesB64 = await generateAdVisuals(selectedAngle, mainAsset, customPrompt, {
          numberOfImages: imageOptions.count, 
          aspectRatio: imageOptions.aspectRatio, 
          useSuperRealism,
          styleReference: styleRef || undefined, 
          headline: headlineText, 
          platform: productInfo.platform, 
          textStyle,
          additionalAssets: [extraAsset1, extraAsset2].filter(Boolean) as UploadedFile[]
        });
        setGeneratedImages(imagesB64);
      } catch (err) { setError('Visual failed.'); } finally { setIsLoading(false); }
    } else {
      if (!selectedAngle) return;
      setIsLoading(true);
      startVideoLoadingRotation();
      setError(null);
      try {
        const videoUrl = await generateAdVideo(selectedAngle, mainAsset, customPrompt, {
          aspectRatio: videoOptions.aspectRatio.includes('9:16') ? '9:16' : '16:9',
          resolution: videoOptions.resolution as '720p' | '1080p'
        });
        setGeneratedVideoUrl(videoUrl);
      } catch (err) { setError('Video failed.'); } finally { if(videoMessageInterval.current) clearInterval(videoMessageInterval.current); setIsLoading(false); }
    }
  };

  const animateGeneratedImage = async (base64: string) => {
    setGenerationMode('Video');
    setGeneratedImages([]);
    setGeneratedVideoUrl(null);
    const byteString = atob(base64);
    const ab = new ArrayBuffer(byteString.length);
    const ia = new Uint8Array(ab);
    for (let i = 0; i < byteString.length; i++) ia[i] = byteString.charCodeAt(i);
    const blob = new Blob([ab], { type: 'image/png' });
    const virtualFile = new File([blob], "ai-generated-asset.png", { type: 'image/png' });
    setMainAsset({ file: virtualFile, data: base64, mimeType: 'image/png' });
    setStep(AppStep.GENERATE_VISUALS);
  };

  const resetApp = () => {
    setStep(AppStep.LANDING);
    setSelectedAngle(null);
    setGeneratedImages([]);
    setGeneratedVideoUrl(null);
    setMainAsset(null);
    setExtraAsset1(null);
    setExtraAsset2(null);
    setStyleRef(null);
    setHeadlineText('');
    setCustomPrompt('');
  };

  const renderLanding = () => (
    <div className="relative min-h-[90vh] flex flex-col items-center justify-center py-12 px-6 w-full max-w-7xl mx-auto text-center">
      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[140%] h-[140%] bg-brand-primary/10 rounded-full blur-[180px] pointer-events-none"></div>

      {/* Delefin Logo - Large and Floating */}
      <div className="relative z-10 w-40 h-40 md:w-56 md:h-56 mb-16 animate-float drop-shadow-[0_0_30px_rgba(255,77,184,0.4)]">
        <PinkDolphinLogo />
      </div>

      <div className="relative z-10 space-y-10 max-w-5xl mx-auto">
        <h1 className="text-7xl md:text-[10rem] font-bold tracking-tighter text-content-primary leading-[0.9] drop-shadow-2xl">
          {t.landing_title}
        </h1>
        <p className="text-2xl md:text-4xl text-content-secondary max-w-3xl mx-auto leading-tight font-light tracking-tight">
          {t.landing_subtitle}
        </p>

        <div className="pt-16">
          <button 
            onClick={() => setStep(AppStep.DEFINE_PRODUCT)} 
            className="group relative overflow-hidden bg-gradient-to-br from-brand-primary via-brand-secondary to-[#ff4db8] text-white font-bold py-7 px-20 rounded-full text-3xl hover:scale-105 transition-all shadow-[0_25px_80px_-20px_rgba(129,140,248,0.6)] active:scale-95 flex items-center gap-4 mx-auto"
          >
            <span className="relative z-10">{t.btn_start}</span>
            <div className="absolute inset-0 bg-white/20 translate-y-full group-hover:translate-y-0 transition-transform duration-300"></div>
          </button>
        </div>
      </div>
    </div>
  );

  const renderDefineProduct = () => (
    <div className="w-full max-w-4xl mx-auto px-6">
      <div className="bg-surface/60 backdrop-blur-3xl border border-white/10 p-8 md:p-14 rounded-[3rem] shadow-2xl space-y-12">
        <div className="text-center">
           <h2 className="text-4xl md:text-5xl font-bold tracking-tighter text-white mb-2">{t.define_title}</h2>
           <p className="text-content-secondary">Set the stage for high-end conversion.</p>
        </div>

        <div className="grid md:grid-cols-2 gap-x-10 gap-y-12">
            <div className="md:col-span-2 space-y-3">
                <label className="font-bold block text-brand-primary text-xs uppercase tracking-[0.2em]">{t.label_name}</label>
                <input type="text" value={productInfo.name} placeholder={t.placeholder_name} onChange={(e) => setProductInfo({...productInfo, name: e.target.value})} className="w-full p-6 bg-background/50 border border-white/5 rounded-3xl focus:ring-4 focus:ring-brand-primary/20 transition-all outline-none text-xl" />
            </div>
            <div className="space-y-3">
                <label className="font-bold text-brand-primary text-xs uppercase tracking-[0.2em]">{t.label_audience}</label>
                <input type="text" value={productInfo.audience} placeholder={t.placeholder_audience} onChange={(e) => setProductInfo({...productInfo, audience: e.target.value})} className="w-full p-5 bg-background/50 border border-white/5 rounded-2xl focus:ring-4 focus:ring-brand-primary/20 transition-all outline-none" />
            </div>
            <div className="space-y-3">
                <label className="font-bold text-brand-primary text-xs uppercase tracking-[0.2em]">{t.label_selling_points}</label>
                <input value={productInfo.sellingPoints} placeholder={t.placeholder_points} onChange={(e) => setProductInfo({...productInfo, sellingPoints: e.target.value})} className="w-full p-5 bg-background/50 border border-white/5 rounded-2xl focus:ring-4 focus:ring-brand-primary/20 transition-all outline-none" />
            </div>
            <div className="space-y-3">
                <label className="font-bold text-brand-primary text-xs uppercase tracking-[0.2em]">{t.label_goal}</label>
                <select value={productInfo.goal} onChange={(e) => setProductInfo({...productInfo, goal: e.target.value})} className="w-full p-5 bg-background/50 border border-white/5 rounded-2xl appearance-none outline-none focus:ring-4 focus:ring-brand-primary/20 cursor-pointer text-content-primary">
                    {CAMPAIGN_GOALS.map(g => <option key={g} value={g}>{g}</option>)}
                </select>
            </div>
            <div className="space-y-3">
                <label className="font-bold text-brand-primary text-xs uppercase tracking-[0.2em]">{t.label_platform}</label>
                <select value={productInfo.platform} onChange={(e) => setProductInfo({...productInfo, platform: e.target.value})} className="w-full p-5 bg-background/50 border border-white/5 rounded-2xl appearance-none outline-none focus:ring-4 focus:ring-brand-primary/20 cursor-pointer text-content-primary">
                    {['Instagram (2026)', 'TikTok (UGC)', 'FB (High Res)'].map(p => <option key={p} value={p}>{p}</option>)}
                </select>
            </div>
            <div className="md:col-span-2 space-y-3">
                <label className="font-bold text-brand-primary text-xs uppercase tracking-[0.2em]">{t.label_archetype}</label>
                <select value={productInfo.brandArchetype} onChange={(e) => setProductInfo({...productInfo, brandArchetype: e.target.value})} className="w-full p-5 bg-background/50 border border-white/5 rounded-2xl appearance-none outline-none focus:ring-4 focus:ring-brand-primary/20 cursor-pointer text-content-primary">
                    <option value="">Standard Vibe Mix 🎧</option>
                    {Object.entries(brandArchetypes).map(([key, arch]) => (
                        <option key={key} value={key}>{arch[lang].name} — {arch[lang].vibe}</option>
                    ))}
                </select>
            </div>
            <div className="md:col-span-2 mt-8">
                <button onClick={startAngleGeneration} disabled={!productInfo.name} className="w-full bg-gradient-to-r from-brand-primary to-brand-secondary text-white font-bold py-7 px-6 rounded-[2rem] text-2xl transition-all disabled:opacity-20 hover:shadow-2xl hover:scale-[1.02]">
                    {t.btn_brainstorm}
                </button>
            </div>
        </div>
      </div>
    </div>
  );

  const renderGenerateAngles = () => (
    <div className="w-full max-w-6xl mx-auto px-6">
      {isLoading ? <Loader message={loadingMessage} /> : (
        <>
        <div className="text-center mb-16">
            <h2 className="text-5xl font-bold text-white mb-4 tracking-tighter">{t.angle_title}</h2>
            <p className="text-content-secondary text-xl font-light">{t.angle_subtitle}</p>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {adAngles.map((angle, index) => (
            <div key={index} onClick={() => {setSelectedAngle(angle); setCustomPrompt(angle.visual_prompt_idea);}} className={`p-8 rounded-[2.5rem] cursor-pointer border-2 backdrop-blur-xl transition-all flex flex-col justify-between h-full ${selectedAngle?.title === angle.title ? 'bg-brand-primary/20 border-brand-primary ring-2 ring-brand-primary/50 shadow-3xl scale-[1.03]' : 'bg-surface/40 border-white/5 hover:border-brand-primary/30'}`}>
              <div>
                <h3 className="text-3xl font-bold mb-4 text-white tracking-tight">{angle.title}</h3>
                <p className="text-content-secondary text-base leading-relaxed">{angle.description}</p>
              </div>
              <div className="mt-8 text-brand-primary font-bold text-sm uppercase tracking-widest">Selected Strategy ✓</div>
            </div>
          ))}
        </div>
        <div className="mt-20 flex flex-col md:flex-row items-center justify-center gap-8">
            <button onClick={() => setStep(AppStep.DEFINE_PRODUCT)} className="px-12 py-5 font-bold text-xl text-content-secondary hover:text-white transition-colors">{t.btn_back}</button>
            {selectedAngle && <button onClick={() => setStep(AppStep.GENERATE_VISUALS)} className="w-full md:w-auto bg-white text-background font-bold py-5 px-16 rounded-full text-2xl shadow-2xl hover:scale-105 transition-all">{t.btn_next_production}</button>}
        </div>
        </>
      )}
    </div>
  );

  const renderGenerateVisuals = () => {
    if (isLoading) return <Loader message={loadingMessage} />;

    if (generatedImages.length > 0 || generatedVideoUrl) {
      return (
        <div className="text-center space-y-16 px-6">
            <div>
                <h2 className="text-5xl md:text-6xl font-bold mb-4 tracking-tighter">{t.production_complete}</h2>
                <p className="text-content-secondary text-xl font-light">{t.production_subtitle}</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-10 max-w-7xl mx-auto">
              {generatedImages.map((img, i) => (
                  <div key={i} className="bg-surface/40 backdrop-blur-xl p-5 rounded-[3rem] border border-white/10 shadow-3xl space-y-6 group">
                    <div className="relative aspect-square overflow-hidden rounded-[2.5rem]">
                        <img src={`data:image/png;base64,${img}`} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" />
                        <div className="absolute inset-0 bg-background/70 md:opacity-0 group-hover:opacity-100 flex items-center justify-center gap-6 transition-all">
                            <a href={`data:image/png;base64,${img}`} download={`ugc-${i+1}.png`} className="p-5 bg-white text-background rounded-full hover:scale-110 transition-transform shadow-2xl">
                                <DownloadIcon className="w-8 h-8" />
                            </a>
                        </div>
                    </div>
                    <button onClick={() => animateGeneratedImage(img)} className="w-full py-4 px-6 bg-[#ff4db8]/10 border border-[#ff4db8]/30 text-[#ff4db8] font-bold rounded-2xl hover:bg-[#ff4db8] hover:text-white transition-all flex items-center justify-center gap-3 text-lg">
                        <VideoIcon className="w-6 h-6" /> {t.btn_animate}
                    </button>
                  </div>
              ))}
            </div>

            {generatedVideoUrl && (
                <div className="max-w-3xl mx-auto bg-surface/60 backdrop-blur-3xl p-6 md:p-10 rounded-[4rem] border border-white/10 shadow-3xl">
                    <video src={generatedVideoUrl} controls autoPlay loop className="w-full h-auto rounded-[2.5rem] shadow-2xl" />
                    <div className="mt-10 flex justify-center">
                         <a href={generatedVideoUrl} download="ugc-video.mp4" className="bg-[#ff4db8] text-white font-bold py-5 px-12 rounded-full flex items-center text-xl shadow-3xl hover:scale-105 transition-all">
                            <DownloadIcon className="w-6 h-6 mr-3" /> {t.btn_download_video}
                         </a>
                    </div>
                </div>
            )}

            <div className="flex flex-col md:flex-row flex-wrap justify-center gap-6 pt-12 pb-24">
               <button onClick={() => { setGeneratedImages([]); setGeneratedVideoUrl(null); }} className="bg-white/5 border border-white/10 text-content-primary font-bold py-5 px-12 rounded-full hover:bg-white/10 transition-all text-xl">
                   {t.btn_refine_production}
               </button>
               {generatedImages.length > 0 && (
                   <button onClick={handleDownloadAll} disabled={isZipping} className="bg-brand-secondary text-white font-bold py-5 px-12 rounded-full flex items-center shadow-2xl text-xl justify-center">
                       {isZipping ? '...' : t.btn_download_zip}
                   </button>
               )}
               <button onClick={resetApp} className="bg-brand-primary text-white font-bold py-5 px-12 rounded-full shadow-2xl hover:scale-105 transition-all text-xl">
                   {t.btn_new_campaign}
               </button>
            </div>
        </div>
      );
    }

    return (
      <div className="w-full max-w-7xl mx-auto space-y-16 px-6 pb-24">
        <div className="flex justify-center">
            <div className="bg-surface/40 backdrop-blur-3xl p-2 rounded-full flex border border-white/10 shadow-3xl">
                <button onClick={() => setGenerationMode('Image')} className={`px-12 md:px-20 py-4 rounded-full text-lg md:text-xl font-bold transition-all ${generationMode === 'Image' ? 'bg-brand-primary text-white shadow-2xl' : 'text-content-secondary hover:text-white'}`}>{t.mode_static}</button>
                <button onClick={() => setGenerationMode('Video')} className={`px-12 md:px-20 py-4 rounded-full text-lg md:text-xl font-bold transition-all ${generationMode === 'Video' ? 'bg-brand-primary text-white shadow-2xl' : 'text-content-secondary hover:text-white'}`}>{t.mode_video}</button>
            </div>
        </div>
        <div className="grid lg:grid-cols-3 gap-10 items-stretch">
            <div className="bg-surface/40 backdrop-blur-xl p-8 md:p-10 rounded-[3rem] border border-white/10 space-y-10">
                <h3 className="font-bold text-2xl tracking-tight text-white">{t.upload_main} 📸</h3>
                <div className="grid grid-cols-2 gap-6">
                    <div className="col-span-2">
                         <FileUploader id="main" label={t.upload_main} uploadedFile={mainAsset} onFileProcessed={setMainAsset} onError={setError} />
                    </div>
                    <FileUploader id="extra1" label={t.upload_extra1} uploadedFile={extraAsset1} onFileProcessed={setExtraAsset1} onError={setError} compact />
                    <FileUploader id="extra2" label={t.upload_extra2} uploadedFile={extraAsset2} onFileProcessed={setExtraAsset2} onError={setError} compact />
                </div>
                <FileUploader id="style" label={t.upload_style} uploadedFile={styleRef} onFileProcessed={setStyleRef} onError={setError} compact />
            </div>

            <div className="bg-surface/40 backdrop-blur-xl p-8 md:p-10 rounded-[3rem] border border-white/10 space-y-10">
                <h3 className="font-bold text-2xl tracking-tight text-white">Ad Detail ✍️</h3>
                <div className="space-y-8">
                    <div>
                        <label className="block mb-3 font-bold text-xs uppercase tracking-[0.2em] text-brand-primary">{t.label_headline}</label>
                        <input value={headlineText} placeholder={t.placeholder_headline} onChange={(e) => setHeadlineText(e.target.value)} className="w-full p-5 bg-background/50 border border-white/5 rounded-2xl focus:ring-4 focus:ring-brand-primary/20" />
                    </div>
                    <div>
                        <label className="block mb-3 font-bold text-xs uppercase tracking-[0.2em] text-brand-primary">{t.label_directives}</label>
                        <textarea value={customPrompt} placeholder={t.placeholder_directives} onChange={(e) => setCustomPrompt(e.target.value)} rows={7} className="w-full p-5 bg-background/50 border border-white/5 rounded-2xl resize-none focus:ring-4 focus:ring-brand-primary/20" />
                    </div>
                </div>
            </div>

            <div className="bg-surface/40 backdrop-blur-xl p-8 md:p-10 rounded-[3rem] border border-white/10 flex flex-col justify-between">
                <div className="space-y-10">
                    <h3 className="font-bold text-2xl tracking-tight text-white">Engine Settings ⚙️</h3>
                    <div className="grid grid-cols-2 gap-6">
                        <div>
                            <label className="block mb-3 font-bold text-[10px] uppercase tracking-widest text-brand-primary">{t.label_ratio}</label>
                            <select value={imageOptions.aspectRatio} onChange={(e) => setImageOptions({...imageOptions, aspectRatio: e.target.value})} className="w-full p-4 bg-background/50 border border-white/5 rounded-2xl text-sm font-bold">
                                <option>Square (1:1)</option>
                                <option>Vertical (9:16)</option>
                                <option>Wide (16:9)</option>
                            </select>
                        </div>
                        <div>
                            <label className="block mb-3 font-bold text-[10px] uppercase tracking-widest text-brand-primary">{t.label_variations}</label>
                            <select value={imageOptions.count} onChange={(e) => setImageOptions({...imageOptions, count: parseInt(e.target.value)})} className="w-full p-4 bg-background/50 border border-white/5 rounded-2xl text-sm font-bold">
                                {[1, 2, 3, 4].map(n => <option key={n} value={n}>{n}</option>)}
                            </select>
                        </div>
                    </div>
                    <div className="p-6 bg-background/50 border border-white/5 rounded-[2rem] flex items-center justify-between">
                        <label className="font-bold text-sm text-white">{t.label_realism} 💎</label>
                        <label className="relative inline-flex items-center cursor-pointer">
                            <input type="checkbox" checked={useSuperRealism} onChange={() => setUseSuperRealism(!useSuperRealism)} className="sr-only peer" />
                            <div className="w-14 h-8 bg-white/10 rounded-full peer peer-checked:bg-brand-primary after:content-[''] after:absolute after:top-[4px] after:left-[4px] after:bg-white after:rounded-full after:h-6 after:w-6 after:transition-all peer-checked:after:translate-x-6"></div>
                        </label>
                    </div>
                </div>
                <div className="space-y-6 pt-12">
                    {error && <p className="text-[#ff4db8] text-sm text-center font-bold animate-pulse">{error}</p>}
                    <button onClick={startGeneration} className="w-full bg-gradient-to-br from-brand-primary via-brand-secondary to-[#ff4db8] text-white font-bold py-6 rounded-[2rem] text-2xl shadow-3xl hover:scale-[1.03] transition-all flex items-center justify-center gap-4">
                        <SparklesIcon className="w-8 h-8" /> {t.btn_produce}
                    </button>
                    <button onClick={() => setStep(AppStep.GENERATE_ANGLES)} className="w-full text-content-secondary hover:text-white font-bold py-2 transition-all">{t.btn_back}</button>
                </div>
            </div>
        </div>
      </div>
    );
  };

  if (isCheckingApiKey) return <div className="min-h-screen flex items-center justify-center bg-background"><Loader message="Loading UGC Engine..." /></div>;

  if (!isApiKeyReady) {
    return (
        <div className="min-h-screen flex flex-col items-center justify-center p-8 bg-background">
            <div className="p-16 bg-surface/60 backdrop-blur-3xl border border-white/10 rounded-[4rem] shadow-3xl max-w-xl text-center space-y-12">
                <div className="w-32 h-32 mx-auto animate-pulse">
                   <PinkDolphinLogo />
                </div>
                <div className="space-y-4">
                  <h1 className="text-5xl font-bold tracking-tight text-white">{t.activation_title}</h1>
                  <p className="text-content-secondary text-xl font-light">{t.activation_subtitle}</p>
                </div>
                <button onClick={handleSelectKey} className="w-full bg-white text-background font-bold py-6 px-10 rounded-[2rem] text-2xl hover:shadow-[0_0_50px_rgba(255,255,255,0.3)] transition-all">
                  {t.btn_select_key}
                </button>
            </div>
        </div>
    );
  }

  const renderContent = () => {
    switch (step) {
      case AppStep.LANDING: return renderLanding();
      case AppStep.DEFINE_PRODUCT: return renderDefineProduct();
      case AppStep.GENERATE_ANGLES: return renderGenerateAngles();
      case AppStep.GENERATE_VISUALS: return renderGenerateVisuals();
      default: return renderLanding();
    }
  };

  return (
    <div className="min-h-screen w-full flex flex-col items-center p-6 md:p-12 bg-background text-content-primary relative overflow-x-hidden">
        {/* Dynamic Background Accents */}
        <div className="fixed inset-0 pointer-events-none overflow-hidden">
            <div className="absolute top-[-20%] left-[-10%] w-[70%] h-[70%] bg-brand-primary/5 rounded-full blur-[150px]"></div>
            <div className="absolute bottom-[-15%] right-[-5%] w-[60%] h-[60%] bg-[#ff4db8]/5 rounded-full blur-[150px]"></div>
        </div>

        <div className="absolute top-6 right-6 md:top-10 md:right-10 z-50">
          <div className="bg-white/5 backdrop-blur-xl border border-white/10 p-1.5 rounded-full flex shadow-3xl">
            <button onClick={() => setLang('en')} className={`px-6 py-2.5 rounded-full text-xs font-bold transition-all tracking-widest ${lang === 'en' ? 'bg-white text-background shadow-xl' : 'text-content-secondary hover:text-white'}`}>EN</button>
            <button onClick={() => setLang('da')} className={`px-6 py-2.5 rounded-full text-xs font-bold transition-all tracking-widest ${lang === 'da' ? 'bg-white text-background shadow-xl' : 'text-content-secondary hover:text-white'}`}>DA</button>
          </div>
        </div>

        <div className="relative z-10 w-full flex flex-col items-center max-w-7xl mx-auto">
            {step !== AppStep.LANDING && (
                <header className="w-full mb-16 text-center space-y-10">
                    <div className="flex flex-col items-center space-y-4">
                        <div className="w-20 h-20 cursor-pointer drop-shadow-[0_0_20px_rgba(255,77,184,0.3)]" onClick={resetApp}>
                            <PinkDolphinLogo />
                        </div>
                        <h1 className="text-4xl md:text-5xl font-bold cursor-pointer tracking-tighter text-white" onClick={resetApp}>
                           {t.landing_title}
                        </h1>
                    </div>
                    <Stepper currentStepEnum={step} onStepClick={(s) => setStep(s)} />
                </header>
            )}
            <main className="w-full">{renderContent()}</main>
        </div>

        <style>{`
          @keyframes float {
            0%, 100% { transform: translateY(0px) rotate(0deg); }
            50% { transform: translateY(-20px) rotate(2deg); }
          }
          .animate-float {
            animation: float 8s ease-in-out infinite;
          }
          ::-webkit-scrollbar { width: 8px; }
          ::-webkit-scrollbar-track { background: transparent; }
          ::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.05); border-radius: 10px; }
          ::-webkit-scrollbar-thumb:hover { background: rgba(255,255,255,0.1); }
        `}</style>
    </div>
  );
};

const Stepper: React.FC<{ currentStepEnum: AppStep, onStepClick: (s: AppStep) => void }> = ({ currentStepEnum, onStepClick }) => {
    const steps = [AppStep.DEFINE_PRODUCT, AppStep.GENERATE_ANGLES, AppStep.GENERATE_VISUALS];
    if (!steps.includes(currentStepEnum)) return null;
    const labels = ["🧬 DNA", "🧠 Mind", "🎬 Studio"];
    return (
        <nav className="flex items-center justify-center space-x-3 md:space-x-14">
            {steps.map((s, i) => {
                const isActive = currentStepEnum === s;
                const isCompleted = steps.indexOf(currentStepEnum) > i;
                return (
                    <div key={i} className={`flex items-center text-xs md:text-sm font-bold transition-all ${isActive ? 'text-brand-primary' : isCompleted ? 'text-[#ff4db8]' : 'text-content-secondary'}`}>
                        <span className={`h-10 w-10 md:h-12 md:w-12 flex items-center justify-center rounded-full mr-2 md:mr-4 border-2 transition-all ${isActive ? 'bg-brand-primary text-white border-brand-primary shadow-[0_0_30px_rgba(129,140,248,0.5)]' : isCompleted ? 'bg-[#ff4db8]/20 border-[#ff4db8] text-[#ff4db8]' : 'bg-surface/50 border-white/5'}`}>{i+1}</span>
                        <span className="hidden sm:inline uppercase tracking-[0.2em]">{labels[i]}</span>
                    </div>
                );
            })}
        </nav>
    );
};

const FileUploader: React.FC<{ id: string, label: string, uploadedFile: UploadedFile | null, onFileProcessed: (f: UploadedFile) => void, onError: (m: string) => void, compact?: boolean }> = ({ id, label, uploadedFile, onFileProcessed, onError, compact }) => {
    const processFile = (file: File) => {
        if (file && file.type.startsWith('image/')) {
            const reader = new FileReader();
            reader.onloadend = () => {
                const base64 = (reader.result as string).split(',')[1];
                onFileProcessed({ file, data: base64, mimeType: file.type });
            };
            reader.readAsDataURL(file);
        }
    };
    return (
        <div className="w-full">
            <label className="block mb-3 font-bold text-[10px] text-content-secondary uppercase tracking-[0.2em]">{label}</label>
            <label htmlFor={id} className={`relative flex flex-col items-center justify-center border-2 border-dashed border-white/10 rounded-3xl cursor-pointer hover:border-brand-primary hover:bg-brand-primary/5 transition-all group overflow-hidden ${compact ? 'p-4 min-h-[120px] md:min-h-[160px]' : 'p-8 min-h-[180px] md:min-h-[260px]'}`}>
                <input id={id} type="file" onChange={(e) => e.target.files?.[0] && processFile(e.target.files[0])} accept="image/*" className="hidden" />
                {!uploadedFile ? (
                    <>
                        <UploadIcon className={`text-content-secondary group-hover:text-brand-primary transition-colors ${compact ? 'w-6 h-6 mb-2' : 'w-10 h-10 mb-5'}`} />
                        <p className={`text-center font-bold uppercase tracking-widest ${compact ? 'text-[8px]' : 'text-xs'}`}>Select</p>
                    </>
                ) : (
                    <div className="relative w-full h-full flex items-center justify-center">
                        <img src={URL.createObjectURL(uploadedFile.file)} className="max-h-full max-w-full rounded-2xl object-contain shadow-2xl" />
                        <div className="absolute inset-0 bg-background/60 md:opacity-0 group-hover:opacity-100 flex items-center justify-center transition-all">
                             <p className="text-white text-xs font-bold bg-brand-primary px-5 py-2 rounded-full shadow-2xl">Replace</p>
                        </div>
                    </div>
                )}
            </label>
            {uploadedFile && <p className="mt-3 text-[9px] text-content-secondary truncate text-center font-mono opacity-50 uppercase">{uploadedFile.file.name}</p>}
        </div>
    );
};

