const Stepper: React.FC<{ currentStepEnum: AppStep, onStepClick: (s: AppStep) => void }> = ({ currentStepEnum, onStepClick }) => {
    const steps = [AppStep.DEFINE_PRODUCT, AppStep.GENERATE_ANGLES, AppStep.GENERATE_VISUALS];
    if (!steps.includes(currentStepEnum)) return null;
    const labels = ["DNA", "Mind", "Studio"];
    return (
        <nav className="flex items-center justify-center space-x-2 md:space-x-8">
            {steps.map((s, i) => {
                const isActive = currentStepEnum === s;
                const isCompleted = steps.indexOf(currentStepEnum) > i;
                return (
                    <div key={i} className={`flex items-center text-[10px] font-bold transition-all ${isActive ? 'text-brand-primary' : isCompleted ? 'text-[#ff4db8]' : 'text-content-secondary'}`}>
                        <span className={`h-8 w-8 md:h-10 md:w-10 flex items-center justify-center rounded-full mr-2 border-2 transition-all ${isActive ? 'bg-brand-primary text-white border-brand-primary shadow-lg' : isCompleted ? 'bg-[#ff4db8]/10 border-[#ff4db8] text-[#ff4db8]' : 'bg-surface/30 border-white/5'}`}>{i+1}</span>
                        <span className="hidden sm:inline uppercase tracking-widest">{labels[i]}</span>
                    </div>
                );
            })}
        </nav>
    );
};

const FileUploader: React.FC<{ id: string, label: string, uploadedFile: UploadedFile | null, onFileProcessed: (f: UploadedFile) => void, onError: (m: string) => void, compact?: boolean }> = ({ id, label, uploadedFile, onFileProcessed, onError, compact }) => {
    const processFile = (file: File) => {
        if (file && file.type.startsWith('image/')) {
            const reader = new FileReader();
            reader.onloadend = () => {
                const base64 = (reader.result as string).split(',')[1];
                onFileProcessed({ file, data: base64, mimeType: file.type });
            };
            reader.readAsDataURL(file);
        }
    };
    return (
        <div className="w-full">
            <label className="block mb-2 font-bold text-[8px] md:text-[9px] text-content-secondary uppercase tracking-[0.2em]">{label}</label>
            <label htmlFor={id} className={`relative flex flex-col items-center justify-center border-2 border-dashed border-white/10 rounded-2xl cursor-pointer hover:border-brand-primary hover:bg-brand-primary/5 transition-all group overflow-hidden ${compact ? 'p-3 min-h-[90px] md:min-h-[120px]' : 'p-6 min-h-[140px] md:min-h-[200px]'}`}>
                <input id={id} type="file" onChange={(e) => e.target.files?.[0] && processFile(e.target.files[0])} accept="image/*" className="hidden" />
                {!uploadedFile ? (
                    <>
                        <UploadIcon className={`text-content-secondary group-hover:text-brand-primary transition-colors ${compact ? 'w-5 h-5 mb-1' : 'w-8 h-8 mb-4'}`} />
                        <p className={`text-center font-bold uppercase tracking-widest text-[8px]`}>Tap</p>
                    </>
                ) : (
                    <div className="relative w-full h-full flex items-center justify-center">
                        <img src={URL.createObjectURL(uploadedFile.file)} className="max-h-full max-w-full rounded-xl object-contain shadow-lg" />
                        <div className="absolute inset-0 bg-background/50 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                             <p className="text-white text-[8px] font-bold bg-brand-primary px-3 py-1 rounded-full uppercase">Edit</p>
                        </div>
                    </div>
                )}
            </label>
        </div>
    );
};

