  useEffect(() => {
    const checkKey = async () => {
        if (window.aistudio && await window.aistudio.hasSelectedApiKey()) setIsApiKeyReady(true);
        setIsCheckingApiKey(false);
    };
    checkKey();
  }, []);

  const handleSelectKey = async () => {
    if (window.aistudio) {
        try { await window.aistudio.openSelectKey(); setIsApiKeyReady(true); } catch (e) {}
    }
  };

  const startVideoLoadingRotation = () => {
    const msgs = lang === 'da' ? ["Initialiserer...", "Analyserer...", "Skaber magi..."] : ["Initializing...", "Analyzing...", "Creating magic..."];
    let index = 0;
    setLoadingMessage(msgs[0]);
    videoMessageInterval.current = window.setInterval(() => {
        index = (index + 1) % msgs.length;
        setLoadingMessage(msgs[index]);
    }, 8000);
  };

  const handleDownloadAll = async () => {
    if (generatedImages.length === 0) return;
    setIsZipping(true);
    try {
      const zip = new JSZip();
      generatedImages.forEach((imgBase64, index) => {
        zip.file(`ad-${index + 1}.png`, imgBase64, { base64: true });
      });
      const blob = await zip.generateAsync({ type: 'blob' });
      saveAs(blob, 'ugc-creatives.zip');
    } catch (err) {
      setError("Download failed.");
    } finally {
      setIsZipping(false);
    }
  };

  const startAngleGeneration = async () => {
    setIsLoading(true);
    setLoadingMessage("🧠 Brainstorming strategy...");
    setError(null);
    try {
      const angles = await generateAdAngles(productInfo, lang);
      setAdAngles(angles);
      setStep(AppStep.GENERATE_ANGLES);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Error');
    } finally { setIsLoading(false); }
  };

  const startGeneration = async () => {
    if (generationMode === 'Image') {
      if (!selectedAngle || !mainAsset) {
          setError("Upload main image first! 📸");
          return;
      }
      setIsLoading(true);
      setLoadingMessage("🎨 Painting assets...");
      setError(null);
      try {
        const imagesB64 = await generateAdVisuals(selectedAngle, mainAsset, customPrompt, {
          numberOfImages: imageOptions.count, 
          aspectRatio: imageOptions.aspectRatio, 
          useSuperRealism,
          styleReference: styleRef || undefined, 
          headline: headlineText, 
          platform: productInfo.platform, 
          textStyle,
          additionalAssets: [extraAsset1, extraAsset2].filter(Boolean) as UploadedFile[]
        });
        setGeneratedImages(imagesB64);
      } catch (err) { setError('Visual failed.'); } finally { setIsLoading(false); }
    } else {
      if (!selectedAngle) return;
      setIsLoading(true);
      startVideoLoadingRotation();
      setError(null);
      try {
        const videoUrl = await generateAdVideo(selectedAngle, mainAsset, customPrompt, {
          aspectRatio: videoOptions.aspectRatio.includes('9:16') ? '9:16' : '16:9',
          resolution: videoOptions.resolution as '720p' | '1080p'
        });
        setGeneratedVideoUrl(videoUrl);
      } catch (err) { setError('Video failed.'); } finally { if(videoMessageInterval.current) clearInterval(videoMessageInterval.current); setIsLoading(false); }
    }
  };

  const animateGeneratedImage = async (base64: string) => {
    setGenerationMode('Video');
    setGeneratedImages([]);
    setGeneratedVideoUrl(null);
    const byteString = atob(base64);
    const ab = new ArrayBuffer(byteString.length);
    const ia = new Uint8Array(ab);
    for (let i = 0; i < byteString.length; i++) ia[i] = byteString.charCodeAt(i);
    const blob = new Blob([ab], { type: 'image/png' });
    const virtualFile = new File([blob], "ai-generated-asset.png", { type: 'image/png' });
    setMainAsset({ file: virtualFile, data: base64, mimeType: 'image/png' });
    setStep(AppStep.GENERATE_VISUALS);
  };

  const resetApp = () => {
    setStep(AppStep.LANDING);
    setSelectedAngle(null);
    setGeneratedImages([]);
    setGeneratedVideoUrl(null);
    setMainAsset(null);
    setExtraAsset1(null);
    setExtraAsset2(null);
    setStyleRef(null);
    setHeadlineText('');
    setCustomPrompt('');
  };

  const renderLanding = () => (
    <div className="relative min-h-[70vh] flex flex-col items-center justify-center py-6 px-4 md:px-8 w-full max-w-4xl mx-auto text-center">
      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[100%] h-[100%] bg-brand-primary/5 rounded-full blur-[120px] pointer-events-none"></div>

      <div className="relative z-10 w-20 h-20 md:w-28 md:h-28 mb-8 animate-float drop-shadow-[0_0_15px_rgba(255,77,184,0.3)]">
        <PinkDolphinLogo />
      </div>

      <div className="relative z-10 space-y-4 md:space-y-6">
        <h1 className="text-4xl md:text-7xl font-bold tracking-tighter text-content-primary leading-[1] drop-shadow-sm uppercase">
          {t.landing_title}
        </h1>
        <p className="text-base md:text-xl text-content-secondary max-w-xl mx-auto leading-tight font-light tracking-tight opacity-80">
          {t.landing_subtitle}
        </p>

        <div className="pt-8">
          <button 
            onClick={() => setStep(AppStep.DEFINE_PRODUCT)} 
            className="group relative overflow-hidden bg-white text-background font-bold py-4 px-10 rounded-full text-lg md:text-xl hover:bg-brand-primary hover:text-white transition-all shadow-[0_10px_40px_-10px_rgba(255,255,255,0.2)] active:scale-95 flex items-center gap-2 mx-auto"
          >
            <span className="relative z-10 uppercase tracking-widest">{t.btn_start}</span>
            <div className="absolute inset-0 bg-brand-primary translate-y-full group-hover:translate-y-0 transition-transform duration-300"></div>
          </button>
        </div>
      </div>
    </div>
  );

  const renderDefineProduct = () => (
    <div className="w-full max-w-3xl mx-auto px-4">
      <div className="bg-surface/30 backdrop-blur-3xl border border-white/5 p-6 md:p-8 rounded-[1.5rem] md:rounded-[2rem] shadow-xl space-y-6">
        <div className="text-center">
           <h2 className="text-2xl md:text-3xl font-bold tracking-tighter text-white mb-0.5 uppercase">{t.define_title}</h2>
        </div>

        <div className="grid md:grid-cols-2 gap-x-5 gap-y-6">
            <div className="md:col-span-2 space-y-1.5">
                <label className="font-bold block text-brand-primary text-[9px] uppercase tracking-[0.2em]">{t.label_name}</label>
                <input type="text" value={productInfo.name} placeholder={t.placeholder_name} onChange={(e) => setProductInfo({...productInfo, name: e.target.value})} className="w-full p-3.5 bg-background/40 border border-white/5 rounded-xl focus:ring-2 focus:ring-brand-primary/20 transition-all outline-none text-base" />
            </div>
            <div className="space-y-1.5">
                <label className="font-bold text-brand-primary text-[9px] uppercase tracking-[0.2em]">{t.label_audience}</label>
                <input type="text" value={productInfo.audience} placeholder={t.placeholder_audience} onChange={(e) => setProductInfo({...productInfo, audience: e.target.value})} className="w-full p-3.5 bg-background/40 border border-white/5 rounded-xl focus:ring-2 focus:ring-brand-primary/20 transition-all outline-none text-sm" />
            </div>
            <div className="space-y-1.5">
                <label className="font-bold text-brand-primary text-[9px] uppercase tracking-[0.2em]">{t.label_selling_points}</label>
                <input value={productInfo.sellingPoints} placeholder={t.placeholder_points} onChange={(e) => setProductInfo({...productInfo, sellingPoints: e.target.value})} className="w-full p-3.5 bg-background/40 border border-white/5 rounded-xl focus:ring-2 focus:ring-brand-primary/20 transition-all outline-none text-sm" />
            </div>
            <div className="space-y-1.5">
                <label className="font-bold text-brand-primary text-[9px] uppercase tracking-[0.2em]">{t.label_goal}</label>
                <select value={productInfo.goal} onChange={(e) => setProductInfo({...productInfo, goal: e.target.value})} className="w-full p-3.5 bg-background/40 border border-white/5 rounded-xl appearance-none outline-none focus:ring-2 focus:ring-brand-primary/20 cursor-pointer text-content-primary text-sm">
                    {CAMPAIGN_GOALS.map(g => <option key={g} value={g}>{g}</option>)}
                </select>
            </div>
            <div className="space-y-1.5">
                <label className="font-bold text-brand-primary text-[9px] uppercase tracking-[0.2em]">{t.label_platform}</label>
                <select value={productInfo.platform} onChange={(e) => setProductInfo({...productInfo, platform: e.target.value})} className="w-full p-3.5 bg-background/40 border border-white/5 rounded-xl appearance-none outline-none focus:ring-2 focus:ring-brand-primary/20 cursor-pointer text-content-primary text-sm">
                    {['Instagram', 'TikTok', 'Facebook'].map(p => <option key={p} value={p}>{p}</option>)}
                </select>
            </div>
            <div className="md:col-span-2 space-y-1.5">
                <label className="font-bold text-brand-primary text-[9px] uppercase tracking-[0.2em]">{t.label_archetype}</label>
                <select value={productInfo.brandArchetype} onChange={(e) => setProductInfo({...productInfo, brandArchetype: e.target.value})} className="w-full p-3.5 bg-background/40 border border-white/5 rounded-xl appearance-none outline-none focus:ring-2 focus:ring-brand-primary/20 cursor-pointer text-content-primary text-sm">
                    <option value="">Standard Vibe Mix 🎧</option>
                    {Object.entries(brandArchetypes).map(([key, arch]) => (
                        <option key={key} value={key}>{arch[lang].name} — {arch[lang].vibe}</option>
                    ))}
                </select>
            </div>
            <div className="md:col-span-2 mt-4">
                <button onClick={startAngleGeneration} disabled={!productInfo.name} className="w-full bg-brand-primary text-white font-bold py-4 px-6 rounded-xl text-lg transition-all disabled:opacity-20 hover:bg-brand-primary/80 active:scale-[0.99] uppercase tracking-widest">
                    {t.btn_brainstorm}
                </button>
            </div>
        </div>
      </div>
    </div>
  );

  const renderGenerateAngles = () => (
    <div className="w-full max-w-4xl mx-auto px-4">
      {isLoading ? <Loader message={loadingMessage} /> : (
        <>
        <div className="text-center mb-8">
            <h2 className="text-2xl md:text-3xl font-bold text-white mb-1 tracking-tighter uppercase">{t.angle_title}</h2>
            <p className="text-content-secondary text-base font-light opacity-70">{t.angle_subtitle}</p>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {adAngles.map((angle, index) => (
            <div key={index} onClick={() => {setSelectedAngle(angle); setCustomPrompt(angle.visual_prompt_idea);}} className={`group p-5 rounded-[1.2rem] cursor-pointer border backdrop-blur-xl transition-all flex flex-col justify-between h-full ${selectedAngle?.title === angle.title ? 'bg-brand-primary/10 border-brand-primary shadow-lg ring-1 ring-brand-primary/20' : 'bg-surface/20 border-white/5 hover:border-brand-primary/40 hover:bg-surface/30'}`}>
              <div>
                <h3 className="text-xl font-bold mb-2 text-white tracking-tight leading-tight">{angle.title}</h3>
                <p className="text-content-secondary text-xs leading-relaxed opacity-80">{angle.description}</p>
              </div>
              <div className={`mt-4 text-brand-primary font-bold text-[8px] uppercase tracking-widest transition-opacity ${selectedAngle?.title === angle.title ? 'opacity-100' : 'opacity-0'}`}>Selected ✓</div>
            </div>
          ))}
        </div>
        <div className="mt-8 flex flex-col md:flex-row items-center justify-center gap-2">
            <button onClick={() => setStep(AppStep.DEFINE_PRODUCT)} className="px-6 py-2 font-bold text-xs text-content-secondary hover:text-white transition-colors uppercase tracking-widest">{t.btn_back}</button>
            {selectedAngle && <button onClick={() => setStep(AppStep.GENERATE_VISUALS)} className="w-full md:w-auto bg-white text-background font-bold py-3 px-10 rounded-full text-base shadow-lg hover:bg-brand-primary hover:text-white transition-all uppercase tracking-widest">{t.btn_next_production}</button>}
        </div>
        </>
      )}
    </div>
  );

  const renderGenerateVisuals = () => {
    if (isLoading) return <Loader message={loadingMessage} />;

    if (generatedImages.length > 0 || generatedVideoUrl) {
      return (
        <div className="text-center space-y-8 px-4">
            <div>
                <h2 className="text-3xl font-bold mb-1 tracking-tighter uppercase">{t.production_complete}</h2>
                <p className="text-content-secondary text-base font-light opacity-70">{t.production_subtitle}</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5 max-w-5xl mx-auto">
              {generatedImages.map((img, i) => (
                  <div key={i} className="bg-surface/20 backdrop-blur-xl p-3 rounded-[1.5rem] border border-white/5 shadow-xl space-y-3 group">
                    <div className="relative aspect-square overflow-hidden rounded-[1rem]">
                        <img src={`data:image/png;base64,${img}`} className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105" />
                        <div className="absolute inset-0 bg-background/50 opacity-0 group-hover:opacity-100 flex items-center justify-center gap-3 transition-all">
                            <a href={`data:image/png;base64,${img}`} download={`ugc-${i+1}.png`} className="p-3 bg-white text-background rounded-full hover:scale-105 transition-transform shadow-md">
                                <DownloadIcon className="w-5 h-5" />
                            </a>
                        </div>
                    </div>
                    <button onClick={() => animateGeneratedImage(img)} className="w-full py-2.5 px-4 bg-[#ff4db8]/5 border border-[#ff4db8]/10 text-[#ff4db8] font-bold rounded-lg hover:bg-[#ff4db8] hover:text-white transition-all flex items-center justify-center gap-2 text-[10px] uppercase tracking-widest">
                        <VideoIcon className="w-4 h-4" /> {t.btn_animate}
                    </button>
                  </div>
              ))}
            </div>

            {generatedVideoUrl && (
                <div className="max-w-xl mx-auto bg-surface/40 backdrop-blur-3xl p-3 md:p-4 rounded-[2rem] border border-white/5 shadow-2xl">
                    <video src={generatedVideoUrl} controls autoPlay loop className="w-full h-auto rounded-[1.2rem] shadow-lg" />
                    <div className="mt-6 flex justify-center">
                         <a href={generatedVideoUrl} download="ugc-video.mp4" className="bg-[#ff4db8] text-white font-bold py-3 px-8 rounded-full flex items-center text-base shadow-xl hover:bg-[#ff4db8]/90 transition-all uppercase tracking-widest">
                            <DownloadIcon className="w-4 h-4 mr-2" /> {t.btn_download_video}
                         </a>
                    </div>
                </div>
            )}

            <div className="flex flex-col md:flex-row flex-wrap justify-center gap-3 pt-6 pb-12">
               <button onClick={() => { setGeneratedImages([]); setGeneratedVideoUrl(null); }} className="bg-white/5 border border-white/5 text-content-primary font-bold py-3 px-8 rounded-full hover:bg-white/10 transition-all text-xs uppercase tracking-widest">
                   {t.btn_refine_production}
               </button>
               {generatedImages.length > 0 && (
                   <button onClick={handleDownloadAll} disabled={isZipping} className="bg-brand-secondary text-white font-bold py-3 px-8 rounded-full flex items-center shadow-lg text-xs justify-center uppercase tracking-widest">
                       {isZipping ? '...' : t.btn_download_zip}
                   </button>
               )}
               <button onClick={resetApp} className="bg-brand-primary text-white font-bold py-3 px-8 rounded-full shadow-lg hover:bg-brand-primary/80 transition-all text-xs uppercase tracking-widest">
                   {t.btn_new_campaign}
               </button>
            </div>
        </div>
      );
    }

    return (
      <div className="w-full max-w-5xl mx-auto space-y-10 px-4 pb-16">
        <div className="flex justify-center">
            <div className="bg-surface/20 backdrop-blur-3xl p-0.5 rounded-full flex border border-white/5 shadow-xl">
                <button onClick={() => setGenerationMode('Image')} className={`px-8 md:px-12 py-2 rounded-full text-xs font-bold transition-all uppercase tracking-widest ${generationMode === 'Image' ? 'bg-white text-background shadow-md' : 'text-content-secondary hover:text-white'}`}>{t.mode_static}</button>
                <button onClick={() => setGenerationMode('Video')} className={`px-8 md:px-12 py-2 rounded-full text-xs font-bold transition-all uppercase tracking-widest ${generationMode === 'Video' ? 'bg-white text-background shadow-md' : 'text-content-secondary hover:text-white'}`}>{t.mode_video}</button>
            </div>
        </div>
        <div className="grid lg:grid-cols-3 gap-5 items-stretch">
            <div className="bg-surface/20 backdrop-blur-xl p-5 md:p-6 rounded-[1.5rem] border border-white/5 space-y-5">
                <h3 className="font-bold text-lg tracking-tight text-white uppercase">{t.upload_main} 📸</h3>
                <div className="grid grid-cols-2 gap-3">
                    <div className="col-span-2">
                         <FileUploader id="main" label={t.upload_main} uploadedFile={mainAsset} onFileProcessed={setMainAsset} onError={setError} />
                    </div>
                    <FileUploader id="extra1" label={t.upload_extra1} uploadedFile={extraAsset1} onFileProcessed={setExtraAsset1} onError={setError} compact />
                    <FileUploader id="extra2" label={t.upload_extra2} uploadedFile={extraAsset2} onFileProcessed={setExtraAsset2} onError={setError} compact />
                </div>
                <FileUploader id="style" label={t.upload_style} uploadedFile={styleRef} onFileProcessed={setStyleRef} onError={setError} compact />
            </div>

            <div className="bg-surface/20 backdrop-blur-xl p-5 md:p-6 rounded-[1.5rem] border border-white/5 space-y-6">
                <h3 className="font-bold text-lg tracking-tight text-white uppercase">Ad Detail ✍️</h3>
                <div className="space-y-5">
                    <div>
                        <label className="block mb-1.5 font-bold text-[8px] uppercase tracking-widest text-brand-primary">{t.label_headline}</label>
                        <input value={headlineText} placeholder={t.placeholder_headline} onChange={(e) => setHeadlineText(e.target.value)} className="w-full p-3 bg-background/40 border border-white/5 rounded-lg focus:ring-2 focus:ring-brand-primary/10 text-sm" />
                    </div>
                    <div>
                        <label className="block mb-1.5 font-bold text-[8px] uppercase tracking-widest text-brand-primary">{t.label_directives}</label>
                        <textarea value={customPrompt} placeholder={t.placeholder_directives} onChange={(e) => setCustomPrompt(e.target.value)} rows={5} className="w-full p-3 bg-background/40 border border-white/5 rounded-lg resize-none focus:ring-2 focus:ring-brand-primary/10 text-sm" />
                    </div>
                </div>
            </div>

            <div className="bg-surface/20 backdrop-blur-xl p-5 md:p-6 rounded-[1.5rem] border border-white/5 flex flex-col justify-between">
                <div className="space-y-6">
                    <h3 className="font-bold text-lg tracking-tight text-white uppercase">Engine ⚙️</h3>
                    <div className="grid grid-cols-2 gap-3">
                        <div>
                            <label className="block mb-1.5 font-bold text-[8px] uppercase tracking-widest text-brand-primary">{t.label_ratio}</label>
                            <select value={imageOptions.aspectRatio} onChange={(e) => setImageOptions({...imageOptions, aspectRatio: e.target.value})} className="w-full p-2.5 bg-background/40 border border-white/5 rounded-lg text-xs font-bold cursor-pointer">
                                <option>1:1</option>
                                <option>9:16</option>
                                <option>16:9</option>
                            </select>
                        </div>
                        <div>
                            <label className="block mb-1.5 font-bold text-[8px] uppercase tracking-widest text-brand-primary">{t.label_variations}</label>
                            <select value={imageOptions.count} onChange={(e) => setImageOptions({...imageOptions, count: parseInt(e.target.value)})} className="w-full p-2.5 bg-background/40 border border-white/5 rounded-lg text-xs font-bold cursor-pointer">
                                {[1, 2, 3, 4].map(n => <option key={n} value={n}>{n}</option>)}
                            </select>
                        </div>
                    </div>
                    <div className="p-3.5 bg-background/40 border border-white/5 rounded-xl flex items-center justify-between">
                        <label className="font-bold text-[8px] text-white uppercase tracking-widest">{t.label_realism}</label>
                        <label className="relative inline-flex items-center cursor-pointer">
                            <input type="checkbox" checked={useSuperRealism} onChange={() => setUseSuperRealism(!useSuperRealism)} className="sr-only peer" />
                            <div className="w-10 h-5 bg-white/5 rounded-full peer peer-checked:bg-brand-primary after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked:after:translate-x-5"></div>
                        </label>
                    </div>
                </div>
                <div className="space-y-3 pt-8">
                    {error && <p className="text-[#ff4db8] text-[10px] text-center font-bold tracking-tight">{error}</p>}
                    <button onClick={startGeneration} className="w-full bg-brand-primary text-white font-bold py-4 rounded-xl text-lg shadow-lg hover:bg-brand-primary/80 transition-all flex items-center justify-center gap-2 uppercase tracking-widest">
                        <SparklesIcon className="w-5 h-5" /> {t.btn_produce}
                    </button>
                    <button onClick={() => setStep(AppStep.GENERATE_ANGLES)} className="w-full text-content-secondary hover:text-white font-bold py-1 text-[9px] transition-all uppercase tracking-[0.2em]">{t.btn_back}</button>
                </div>
            </div>
        </div>
      </div>
    );
  };

  if (isCheckingApiKey) return <div className="min-h-screen flex items-center justify-center bg-background"><Loader message="Loading UGC Engine..." /></div>;

  if (!isApiKeyReady) {
    return (
        <div className="min-h-screen flex flex-col items-center justify-center p-6 bg-background">
            <div className="p-8 md:p-12 bg-surface/30 backdrop-blur-3xl border border-white/5 rounded-[2rem] shadow-xl max-w-md text-center space-y-6">
                <div className="w-16 h-16 mx-auto">
                   <PinkDolphinLogo />
                </div>
                <div className="space-y-2">
                  <h1 className="text-2xl md:text-3xl font-bold tracking-tight text-white uppercase">{t.activation_title}</h1>
                  <p className="text-content-secondary text-base font-light opacity-70 leading-snug">{t.activation_subtitle}</p>
                </div>
                <button onClick={handleSelectKey} className="w-full bg-white text-background font-bold py-4 px-8 rounded-full text-lg hover:bg-brand-primary hover:text-white transition-all uppercase tracking-widest">
                  {t.btn_select_key}
                </button>
            </div>
        </div>
    );
  }

  const renderContent = () => {
    switch (step) {
      case AppStep.LANDING: return renderLanding();
      case AppStep.DEFINE_PRODUCT: return renderDefineProduct();
      case AppStep.GENERATE_ANGLES: return renderGenerateAngles();
      case AppStep.GENERATE_VISUALS: return renderGenerateVisuals();
      default: return renderLanding();
    }
  };

  return (
    <div className="min-h-screen w-full flex flex-col items-center p-3 md:p-6 bg-background text-content-primary relative overflow-x-hidden">
        <div className="fixed inset-0 pointer-events-none overflow-hidden">
            <div className="absolute top-[-5%] left-[-2%] w-[50%] h-[50%] bg-brand-primary/3 rounded-full blur-[100px]"></div>
            <div className="absolute bottom-[-5%] right-[-2%] w-[40%] h-[40%] bg-[#ff4db8]/3 rounded-full blur-[100px]"></div>
        </div>

        <div className="absolute top-3 right-3 md:top-5 md:right-5 z-50">
          <div className="bg-white/5 backdrop-blur-xl border border-white/5 p-0.5 rounded-full flex shadow-lg">
            <button onClick={() => setLang('en')} className={`px-4 py-1 rounded-full text-[9px] font-bold transition-all uppercase tracking-[0.15em] ${lang === 'en' ? 'bg-white text-background' : 'text-content-secondary hover:text-white'}`}>EN</button>
            <button onClick={() => setLang('da')} className={`px-4 py-1 rounded-full text-[9px] font-bold transition-all uppercase tracking-[0.15em] ${lang === 'da' ? 'bg-white text-background' : 'text-content-secondary hover:text-white'}`}>DA</button>
          </div>
        </div>

        <div className="relative z-10 w-full flex flex-col items-center max-w-5xl mx-auto">
            {step !== AppStep.LANDING && (
