};

const FileUploader: React.FC<{ id: string, label: string, uploadedFile: UploadedFile | null, onFileProcessed: (f: UploadedFile) => void, onError: (m: string) => void, compact?: boolean }> = ({ id, label, uploadedFile, onFileProcessed, onError, compact }) => {
    const processFile = (file: File) => {
        if (file && file.type.startsWith('image/')) {
            const reader = new FileReader();
            reader.onloadend = () => {
                const base64 = (reader.result as string).split(',')[1];
                onFileProcessed({ file, data: base64, mimeType: file.type });
            };
            reader.readAsDataURL(file);
        }
    };
    return (
        <div className="w-full">
            <label className="block mb-1.5 font-bold text-[7px] md:text-[8px] text-content-secondary uppercase tracking-[0.2em]">{label}</label>
            <label htmlFor={id} className={`relative flex flex-col items-center justify-center border border-dashed border-white/10 rounded-xl cursor-pointer hover:border-brand-primary hover:bg-white/5 transition-all group overflow-hidden ${compact ? 'p-2.5 min-h-[70px] md:min-h-[100px]' : 'p-5 min-h-[110px] md:min-h-[160px]'}`}>
                <input id={id} type="file" onChange={(e) => e.target.files?.[0] && processFile(e.target.files[0])} accept="image/*" className="hidden" />
                {!uploadedFile ? (
                    <>
                        <UploadIcon className={`text-content-secondary group-hover:text-brand-primary transition-colors ${compact ? 'w-4 h-4 mb-1' : 'w-6 h-6 mb-3'}`} />
                        <p className={`text-center font-bold uppercase tracking-widest text-[7px] opacity-60 group-hover:opacity-100`}>Tap</p>
