  if (isCheckingApiKey) return <div className="min-h-screen flex items-center justify-center bg-background"><Loader message="Loading UGC Engine..." /></div>;

  if (!isApiKeyReady) {
    return (
        <div className="min-h-screen flex flex-col items-center justify-center p-6 bg-background">
            <div className="p-8 md:p-12 bg-surface/30 backdrop-blur-3xl border border-white/5 rounded-[2rem] shadow-xl max-w-md text-center space-y-6">
