  const renderContent = () => {
    switch (step) {
      case AppStep.LANDING: return renderLanding();
      case AppStep.DEFINE_PRODUCT: return renderDefineProduct();
      case AppStep.GENERATE_ANGLES: return renderGenerateAngles();
      case AppStep.GENERATE_VISUALS: return renderGenerateVisuals();
      default: return renderLanding();
