          input:focus, select:focus, textarea:focus {
            background: rgba(255,255,255,0.02);
            border-color: rgba(129, 140, 248, 0.4);
          }
        `}</style>
    </div>
  );
};

const Stepper: React.FC<{ currentStepEnum: AppStep, onStepClick: (s: AppStep) => void }> = ({ currentStepEnum, onStepClick }) => {
    const steps = [AppStep.DEFINE_PRODUCT, AppStep.GENERATE_ANGLES, AppStep.GENERATE_VISUALS];
    if (!steps.includes(currentStepEnum)) return null;
    const labels = ["DNA", "MIND", "STUDIO"];
    return (
        <nav className="flex items-center justify-center space-x-2 md:space-x-6">
            {steps.map((s, i) => {
                const isActive = currentStepEnum === s;
                const isCompleted = steps.indexOf(currentStepEnum) > i;
                return (
                    <div key={i} className={`flex items-center text-[9px] font-bold transition-all ${isActive ? 'text-brand-primary' : isCompleted ? 'text-[#ff4db8]' : 'text-content-secondary'}`}>
                        <span className={`h-7 w-7 md:h-8 md:w-8 flex items-center justify-center rounded-full mr-2 border transition-all ${isActive ? 'bg-brand-primary text-white border-brand-primary shadow-sm' : isCompleted ? 'bg-[#ff4db8]/5 border-[#ff4db8] text-[#ff4db8]' : 'bg-white/5 border-white/10'}`}>{i+1}</span>
                        <span className="hidden sm:inline uppercase tracking-[0.2em]">{labels[i]}</span>
                    </div>
                );
            })}
        </nav>
    );
};

const FileUploader: React.FC<{ id: string, label: string, uploadedFile: UploadedFile | null, onFileProcessed: (f: UploadedFile) => void, onError: (m: string) => void, compact?: boolean }> = ({ id, label, uploadedFile, onFileProcessed, onError, compact }) => {
    const processFile = (file: File) => {
        if (file && file.type.startsWith('image/')) {
            const reader = new FileReader();
            reader.onloadend = () => {
                const base64 = (reader.result as string).split(',')[1];
                onFileProcessed({ file, data: base64, mimeType: file.type });
            };
            reader.readAsDataURL(file);
        }
    };
    return (
        <div className="w-full">
            <label className="block mb-1.5 font-bold text-[7px] md:text-[8px] text-content-secondary uppercase tracking-[0.2em]">{label}</label>
            <label htmlFor={id} className={`relative flex flex-col items-center justify-center border border-dashed border-white/10 rounded-xl cursor-pointer hover:border-brand-primary hover:bg-white/5 transition-all group overflow-hidden ${compact ? 'p-2.5 min-h-[70px] md:min-h-[100px]' : 'p-5 min-h-[110px] md:min-h-[160px]'}`}>
