};

const Stepper: React.FC<{ currentStepEnum: AppStep, onStepClick: (s: AppStep) => void }> = ({ currentStepEnum, onStepClick }) => {
    const steps = [AppStep.DEFINE_PRODUCT, AppStep.GENERATE_VISUALS];
    if (!steps.includes(currentStepEnum)) return null;
    const labels = ["DNA", "STUDIO"];
    return (
        <nav className="flex items-center justify-center space-x-2 md:space-x-4">
            {steps.map((s, i) => {
                const isActive = currentStepEnum === s;
                const isCompleted = steps.indexOf(currentStepEnum) > i;
                return (
                    <div key={i} className={`flex items-center text-[8px] font-bold transition-all ${isActive ? 'text-brand-primary' : isCompleted ? 'text-[#ff4db8]' : 'text-content-secondary'}`}>
                        <span className={`h-6 w-6 flex items-center justify-center rounded-full mr-1.5 border transition-all ${isActive ? 'bg-brand-primary text-white border-brand-primary shadow-sm' : isCompleted ? 'bg-[#ff4db8]/5 border-[#ff4db8] text-[#ff4db8]' : 'bg-white/5 border-white/10'}`}>{i+1}</span>
                        <span className="hidden sm:inline uppercase tracking-[0.2em]">{labels[i]}</span>
                    </div>
                );
            })}
        </nav>
    );
};

const FileUploader: React.FC<{ id: string, label: string, uploadedFile: UploadedFile | null, onFileProcessed: (f: UploadedFile) => void, onError: (m: string) => void, compact?: boolean }> = ({ id, label, uploadedFile, onFileProcessed, onError, compact }) => {
    const processFile = (file: File) => {
        if (file && file.type.startsWith('image/')) {
            const reader = new FileReader();
            reader.onloadend = () => {
                const base64 = (reader.result as string).split(',')[1];
                onFileProcessed({ file, data: base64, mimeType: file.type });
            };
            reader.readAsDataURL(file);
        }
    };
    return (
        <div className="w-full">
            <label className="block mb-1 font-bold text-[6px] md:text-[7px] text-content-secondary uppercase tracking-[0.2em]">{label}</label>
            <label htmlFor={id} className={`relative flex flex-col items-center justify-center border border-dashed border-white/10 rounded-xl cursor-pointer hover:border-brand-primary hover:bg-white/5 transition-all group overflow-hidden ${compact ? 'p-2 min-h-[60px] md:min-h-[80px]' : 'p-4 min-h-[100px] md:min-h-[140px]'}`}>
                <input id={id} type="file" onChange={(e) => e.target.files?.[0] && processFile(e.target.files[0])} accept="image/*" className="hidden" />
                {!uploadedFile ? (
                    <>
                        <UploadIcon className={`text-content-secondary group-hover:text-brand-primary transition-colors ${compact ? 'w-3 h-3 mb-1' : 'w-5 h-5 mb-2'}`} />
                        <p className={`text-center font-bold uppercase tracking-widest text-[6px] opacity-60 group-hover:opacity-100`}>Tap</p>
                    </>
                ) : (
                    <div className="relative w-full h-full flex items-center justify-center">
                        <img src={URL.createObjectURL(uploadedFile.file)} className="max-h-full max-w-full rounded-lg object-contain" />
                        <div className="absolute inset-0 bg-background/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                             <p className="text-white text-[6px] font-bold bg-brand-primary px-2.5 py-1 rounded-full uppercase tracking-tighter">Edit</p>
                        </div>
                    </div>
                )}
            </label>
        </div>
    );
};

export default App;

