    activation_subtitle: "Vælg en betalt nøgle for features.",
    btn_select_key: "Vælg API-Nøgle 💳",
    btn_magic_prompt: "✨ AI Forslag til Prompt"
  }
};

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('en');
  const t = TRANSLATIONS[lang];
  const [step, setStep] = useState<AppStep>(AppStep.LANDING);
  const [productInfo, setProductInfo] = useState<ProductInfo>({
    name: '', audience: '', sellingPoints: '', goal: CAMPAIGN_GOALS[0], brandArchetype: '', platform: 'Instagram'
  });
  const [generationMode, setGenerationMode] = useState<GenerationMode>('Image');

  const [mainAsset, setMainAsset] = useState<UploadedFile | null>(null);
  const [extraAsset1, setExtraAsset1] = useState<UploadedFile | null>(null);
  const [extraAsset2, setExtraAsset2] = useState<UploadedFile | null>(null);
  const [styleRef, setStyleRef] = useState<UploadedFile | null>(null);

  const [customPrompt, setCustomPrompt] = useState('');
  const [imageOptions, setImageOptions] = useState({ aspectRatio: '1:1', count: 4 });
  const [videoOptions, setVideoOptions] = useState({ aspectRatio: '9:16', resolution: '720p' });
  const [generatedImages, setGeneratedImages] = useState<string[]>([]);
  const [generatedVideoUrl, setGeneratedVideoUrl] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [loadingMessage, setLoadingMessage] = useState('');
  const [isZipping, setIsZipping] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [useSuperRealism, setUseSuperRealism] = useState(true);
  const [isApiKeyReady, setIsApiKeyReady] = useState(false);
  const [isCheckingApiKey, setIsCheckingApiKey] = useState(true);

  const videoMessageInterval = useRef<number | null>(null);

  useEffect(() => {
    const checkKey = async () => {
        if (window.aistudio && await window.aistudio.hasSelectedApiKey()) setIsApiKeyReady(true);
        setIsCheckingApiKey(false);
    };
    checkKey();
  }, []);

  const handleSelectKey = async () => {
    if (window.aistudio) {
        try { await window.aistudio.openSelectKey(); setIsApiKeyReady(true); } catch (e) {}
    }
  };

  const startVideoLoadingRotation = () => {
    const msgs = lang === 'da' 
      ? ["Forbereder video...", "Analyserer bevægelse...", "Skaber filmisk flow...", "Finpudser frames..."] 
      : ["Preparing video...", "Analyzing motion...", "Creating cinematic flow...", "Polishing frames..."];
    let index = 0;
    setLoadingMessage(msgs[0]);
    videoMessageInterval.current = window.setInterval(() => {
        index = (index + 1) % msgs.length;
        setLoadingMessage(msgs[index]);
    }, 8000);
  };

  const handleDownloadAll = async () => {
    if (generatedImages.length === 0) return;
    setIsZipping(true);
    try {
      const zip = new JSZip();
      generatedImages.forEach((imgBase64, index) => {
        zip.file(`ad-${index + 1}.png`, imgBase64, { base64: true });
      });
      const blob = await zip.generateAsync({ type: 'blob' });
      saveAs(blob, 'ugc-creatives.zip');
    } catch (err) {
      setError("Download failed.");
    } finally {
      setIsZipping(false);
    }
  };

  const handleMagicPrompt = async () => {
    setIsLoading(true);
    setLoadingMessage("✨ Thinking like a Director...");
    try {
        const suggestion = await generateSuggestedPrompt(productInfo, lang);
        setCustomPrompt(suggestion);
    } catch (e) {
        setError("Could not suggest prompt.");
    } finally {
        setIsLoading(false);
    }
  };

  const startGeneration = async () => {
    if (generationMode === 'Image') {
      if (!mainAsset) {
          setError("Upload main image first! 📸");
          return;
      }
      setIsLoading(true);
      setLoadingMessage("🎨 Painting assets...");
      setError(null);
      try {
        const imagesB64 = await generateAdVisuals(null, mainAsset, customPrompt, {
          numberOfImages: imageOptions.count, 
          aspectRatio: imageOptions.aspectRatio, 
          useSuperRealism,
          styleReference: styleRef || undefined, 
          headline: '', 
          platform: productInfo.platform, 
          textStyle: 'Classic',
          additionalAssets: [extraAsset1, extraAsset2].filter(Boolean) as UploadedFile[]
        });
        setGeneratedImages(imagesB64);
      } catch (err) { setError('Visual failed.'); } finally { setIsLoading(false); }
    } else {
      setIsLoading(true);
      startVideoLoadingRotation();
      setError(null);
      try {
        const baseForVideo = generatedImages.length > 0 ? {
            file: new File([], "temp.png"),
            data: generatedImages[0],
            mimeType: 'image/png'
        } : mainAsset;

        const videoUrl = await generateAdVideo(null, baseForVideo, customPrompt, {
          aspectRatio: videoOptions.aspectRatio as '16:9' | '9:16',
          resolution: videoOptions.resolution as '720p' | '1080p'
        });
        setGeneratedVideoUrl(videoUrl);
      } catch (err) { setError('Video failed.'); } finally { if(videoMessageInterval.current) clearInterval(videoMessageInterval.current); setIsLoading(false); }
    }
  };

  const animateGeneratedImage = async (base64: string) => {
    setGenerationMode('Video');
    setGeneratedImages([]);
    setGeneratedVideoUrl(null);
    const byteString = atob(base64);
    const ab = new ArrayBuffer(byteString.length);
    const ia = new Uint8Array(ab);
    for (let i = 0; i < byteString.length; i++) ia[i] = byteString.charCodeAt(i);
    const blob = new Blob([ab], { type: 'image/png' });
    const virtualFile = new File([blob], "ai-generated-asset.png", { type: 'image/png' });
    setMainAsset({ file: virtualFile, data: base64, mimeType: 'image/png' });

    // Auto-trigger video production with the selected image
    setTimeout(() => {
        startGeneration();
    }, 500);
  };

  const resetApp = () => {
    setStep(AppStep.LANDING);
    setGeneratedImages([]);
    setGeneratedVideoUrl(null);
    setMainAsset(null);
    setExtraAsset1(null);
    setExtraAsset2(null);
    setStyleRef(null);
    setCustomPrompt('');
  };

  const renderLanding = () => (
    <div className="relative min-h-[70vh] flex flex-col items-center justify-center py-6 px-4 md:px-8 w-full max-w-4xl mx-auto text-center">
      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[100%] h-[100%] bg-brand-primary/5 rounded-full blur-[120px] pointer-events-none"></div>

      <div className="relative z-10 w-16 h-16 md:w-24 md:h-24 mb-6 animate-float drop-shadow-[0_0_15px_rgba(255,77,184,0.3)]">
        <PinkDolphinLogo />
      </div>

      <div className="relative z-10 space-y-3 md:space-y-4">
        <h1 className="text-3xl md:text-6xl font-bold tracking-tighter text-content-primary leading-[1] drop-shadow-sm uppercase">
          {t.landing_title}
        </h1>
        <p className="text-sm md:text-lg text-content-secondary max-w-md mx-auto leading-tight font-light tracking-tight opacity-80">
          {t.landing_subtitle}
        </p>

        <div className="pt-6">
          <button 
            onClick={() => setStep(AppStep.DEFINE_PRODUCT)} 
            className="group relative overflow-hidden bg-white text-background font-bold py-3 px-10 rounded-full text-base md:text-lg hover:bg-brand-primary hover:text-white transition-all shadow-[0_10px_40px_-10px_rgba(255,255,255,0.2)] active:scale-95 flex items-center gap-2 mx-auto"
          >
            <span className="relative z-10 uppercase tracking-widest">{t.btn_start}</span>
            <div className="absolute inset-0 bg-brand-primary translate-y-full group-hover:translate-y-0 transition-transform duration-300"></div>
          </button>
        </div>
      </div>
    </div>
  );

  const renderDefineProduct = () => (
    <div className="w-full max-w-2xl mx-auto px-4">
      <div className="bg-surface/30 backdrop-blur-3xl border border-white/5 p-5 md:p-8 rounded-[1.5rem] shadow-xl space-y-6">
        <div className="text-center">
           <h2 className="text-xl md:text-2xl font-bold tracking-tighter text-white mb-0.5 uppercase">{t.define_title}</h2>
        </div>

        <div className="grid md:grid-cols-2 gap-x-4 gap-y-5">
            <div className="md:col-span-2 space-y-1.5">
                <label className="font-bold block text-brand-primary text-[8px] uppercase tracking-[0.2em]">{t.label_name}</label>
                <input type="text" value={productInfo.name} placeholder={t.placeholder_name} onChange={(e) => setProductInfo({...productInfo, name: e.target.value})} className="w-full p-3 bg-background/40 border border-white/5 rounded-xl focus:ring-2 focus:ring-brand-primary/20 transition-all outline-none text-sm" />
            </div>
            <div className="space-y-1.5">
                <label className="font-bold text-brand-primary text-[8px] uppercase tracking-[0.2em]">{t.label_audience}</label>
                <input type="text" value={productInfo.audience} placeholder={t.placeholder_audience} onChange={(e) => setProductInfo({...productInfo, audience: e.target.value})} className="w-full p-3 bg-background/40 border border-white/5 rounded-xl focus:ring-2 focus:ring-brand-primary/20 transition-all outline-none text-xs" />
            </div>
            <div className="space-y-1.5">
                <label className="font-bold text-brand-primary text-[8px] uppercase tracking-[0.2em]">{t.label_selling_points}</label>
                <input value={productInfo.sellingPoints} placeholder={t.placeholder_points} onChange={(e) => setProductInfo({...productInfo, sellingPoints: e.target.value})} className="w-full p-3 bg-background/40 border border-white/5 rounded-xl focus:ring-2 focus:ring-brand-primary/20 transition-all outline-none text-xs" />
            </div>
            <div className="space-y-1.5">
                <label className="font-bold text-brand-primary text-[8px] uppercase tracking-[0.2em]">{t.label_goal}</label>
                <select value={productInfo.goal} onChange={(e) => setProductInfo({...productInfo, goal: e.target.value})} className="w-full p-3 bg-background/40 border border-white/5 rounded-xl appearance-none outline-none focus:ring-2 focus:ring-brand-primary/20 cursor-pointer text-content-primary text-xs">
                    {CAMPAIGN_GOALS.map(g => <option key={g} value={g}>{g}</option>)}
                </select>
            </div>
            <div className="space-y-1.5">
                <label className="font-bold text-brand-primary text-[8px] uppercase tracking-[0.2em]">{t.label_platform}</label>
                <select value={productInfo.platform} onChange={(e) => setProductInfo({...productInfo, platform: e.target.value})} className="w-full p-3 bg-background/40 border border-white/5 rounded-xl appearance-none outline-none focus:ring-2 focus:ring-brand-primary/20 cursor-pointer text-content-primary text-xs">
                    {['Instagram', 'TikTok', 'Facebook'].map(p => <option key={p} value={p}>{p}</option>)}
                </select>
            </div>
            <div className="md:col-span-2 space-y-1.5">
                <label className="font-bold text-brand-primary text-[8px] uppercase tracking-[0.2em]">{t.label_archetype}</label>
                <select value={productInfo.brandArchetype} onChange={(e) => setProductInfo({...productInfo, brandArchetype: e.target.value})} className="w-full p-3 bg-background/40 border border-white/5 rounded-xl appearance-none outline-none focus:ring-2 focus:ring-brand-primary/20 cursor-pointer text-content-primary text-xs">
                    <option value="">Standard Vibe Mix 🎧</option>
                    {Object.entries(brandArchetypes).map(([key, arch]) => (
                        <option key={key} value={key}>{arch[lang].name} — {arch[lang].vibe}</option>
                    ))}
                </select>
            </div>
            <div className="md:col-span-2 mt-2">
                <button onClick={() => setStep(AppStep.GENERATE_VISUALS)} disabled={!productInfo.name} className="w-full bg-brand-primary text-white font-bold py-3 px-6 rounded-xl text-base transition-all disabled:opacity-20 hover:bg-brand-primary/80 active:scale-[0.99] uppercase tracking-widest">
                    {t.btn_brainstorm}
                </button>
            </div>
        </div>
      </div>
    </div>
  );

  const renderGenerateVisuals = () => {
    if (isLoading) return <Loader message={loadingMessage} />;

    if (generatedImages.length > 0 || generatedVideoUrl) {
      return (
        <div className="text-center space-y-6 px-4">
            <div>
                <h2 className="text-2xl font-bold mb-0.5 tracking-tighter uppercase">{t.production_complete}</h2>
                <p className="text-content-secondary text-sm font-light opacity-70">{t.production_subtitle}</p>
            </div>

            <div className="grid grid-cols-2 md:grid-cols-4 gap-3 max-w-4xl mx-auto">
              {generatedImages.map((img, i) => (
                  <div key={i} className="bg-surface/20 backdrop-blur-xl p-2 rounded-xl border border-white/5 shadow-xl space-y-2 group">
                    <div className="relative aspect-square overflow-hidden rounded-lg">
                        <img src={`data:image/png;base64,${img}`} className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105" />
                        <div className="absolute inset-0 bg-background/50 opacity-0 group-hover:opacity-100 flex items-center justify-center gap-2 transition-all">
                            <a href={`data:image/png;base64,${img}`} download={`ugc-${i+1}.png`} className="p-2 bg-white text-background rounded-full hover:scale-105 transition-transform shadow-md">
                                <DownloadIcon className="w-4 h-4" />
                            </a>
                        </div>
                    </div>
                    <button onClick={() => animateGeneratedImage(img)} className="w-full py-1.5 px-3 bg-[#ff4db8]/5 border border-[#ff4db8]/10 text-[#ff4db8] font-bold rounded-lg hover:bg-[#ff4db8] hover:text-white transition-all flex items-center justify-center gap-1.5 text-[8px] uppercase tracking-widest">
                        <VideoIcon className="w-3 h-3" /> {t.btn_animate}
                    </button>
                  </div>
              ))}
            </div>

            {generatedVideoUrl && (
                <div className="max-w-sm mx-auto bg-surface/40 backdrop-blur-3xl p-3 rounded-[1.5rem] border border-white/5 shadow-2xl">
                    <video src={generatedVideoUrl} controls autoPlay loop className="w-full h-auto rounded-xl shadow-lg" />
                    <div className="mt-4 flex justify-center">
                         <a href={generatedVideoUrl} download="ugc-video.mp4" className="bg-[#ff4db8] text-white font-bold py-2 px-6 rounded-full flex items-center text-xs shadow-xl hover:bg-[#ff4db8]/90 transition-all uppercase tracking-widest">
                            <DownloadIcon className="w-3.5 h-3.5 mr-1.5" /> {t.btn_download_video}
                         </a>
                    </div>
                </div>
            )}

            <div className="flex flex-col md:flex-row flex-wrap justify-center gap-2.5 pt-4 pb-10">
               <button onClick={() => { setGeneratedImages([]); setGeneratedVideoUrl(null); }} className="bg-white/5 border border-white/5 text-content-primary font-bold py-2.5 px-8 rounded-full hover:bg-white/10 transition-all text-[10px] uppercase tracking-widest">
                   {t.btn_refine_production}
               </button>
               {generatedImages.length > 0 && (
                   <button onClick={handleDownloadAll} disabled={isZipping} className="bg-brand-secondary text-white font-bold py-2.5 px-8 rounded-full flex items-center shadow-lg text-[10px] justify-center uppercase tracking-widest">
                       {isZipping ? '...' : t.btn_download_zip}
                   </button>
               )}
               <button onClick={resetApp} className="bg-brand-primary text-white font-bold py-2.5 px-8 rounded-full shadow-lg hover:bg-brand-primary/80 transition-all text-[10px] uppercase tracking-widest">
                   {t.btn_new_campaign}
               </button>
            </div>
        </div>
      );
    }

    return (
      <div className="w-full max-w-4xl mx-auto space-y-8 px-4 pb-12">
        <div className="flex justify-center">
            <div className="bg-surface/20 backdrop-blur-3xl p-0.5 rounded-full flex border border-white/5 shadow-xl">
                <button onClick={() => setGenerationMode('Image')} className={`px-8 md:px-12 py-1.5 rounded-full text-[10px] font-bold transition-all uppercase tracking-widest ${generationMode === 'Image' ? 'bg-white text-background shadow-sm' : 'text-content-secondary hover:text-white'}`}>{t.mode_static}</button>
                <button onClick={() => setGenerationMode('Video')} className={`px-8 md:px-12 py-1.5 rounded-full text-[10px] font-bold transition-all uppercase tracking-widest ${generationMode === 'Video' ? 'bg-white text-background shadow-sm' : 'text-content-secondary hover:text-white'}`}>{t.mode_video}</button>
            </div>
        </div>
        <div className="grid lg:grid-cols-3 gap-4 items-stretch">
            {/* Asset Column */}
            <div className="bg-surface/20 backdrop-blur-xl p-4 rounded-xl border border-white/5 space-y-4">
                <h3 className="font-bold text-base tracking-tight text-white uppercase">{t.upload_main} 📸</h3>
                <div className="grid grid-cols-2 gap-2">
                    <div className="col-span-2">
                         <FileUploader id="main" label={t.upload_main} uploadedFile={mainAsset} onFileProcessed={setMainAsset} onError={setError} />
                    </div>
                    <FileUploader id="extra1" label={t.upload_extra1} uploadedFile={extraAsset1} onFileProcessed={setExtraAsset1} onError={setError} compact />
                    <FileUploader id="extra2" label={t.upload_extra2} uploadedFile={extraAsset2} onFileProcessed={setExtraAsset2} onError={setError} compact />
                </div>
                <FileUploader id="style" label={t.upload_style} uploadedFile={styleRef} onFileProcessed={setStyleRef} onError={setError} compact />
            </div>

            {/* Prompt Column */}
            <div className="bg-surface/20 backdrop-blur-xl p-4 rounded-xl border border-white/5 space-y-4">
                <h3 className="font-bold text-base tracking-tight text-white uppercase">Creative 🌍</h3>
                <div className="space-y-4">
                    <div>
                        <button onClick={handleMagicPrompt} className="w-full mb-2 bg-brand-primary/10 border border-brand-primary/30 text-brand-primary font-bold py-1.5 rounded-lg text-[9px] uppercase tracking-widest hover:bg-brand-primary hover:text-white transition-all">
                            {t.btn_magic_prompt}
                        </button>
                        <label className="block mb-1 font-bold text-[7px] uppercase tracking-widest text-brand-primary">{t.label_directives}</label>
                        <textarea value={customPrompt} placeholder={t.placeholder_directives} onChange={(e) => setCustomPrompt(e.target.value)} rows={10} className="w-full p-2.5 bg-background/40 border border-white/5 rounded-lg resize-none focus:ring-2 focus:ring-brand-primary/10 text-xs" />
                    </div>
                </div>
            </div>

            {/* Engine Column */}
            <div className="bg-surface/20 backdrop-blur-xl p-4 rounded-xl border border-white/5 flex flex-col justify-between">
                <div className="space-y-5">
                    <h3 className="font-bold text-base tracking-tight text-white uppercase">Engine ⚙️</h3>

                    {generationMode === 'Image' ? (
                        <div className="grid grid-cols-2 gap-2">
                            <div>
                                <label className="block mb-1 font-bold text-[7px] uppercase tracking-widest text-brand-primary">{t.label_ratio}</label>
                                <select value={imageOptions.aspectRatio} onChange={(e) => setImageOptions({...imageOptions, aspectRatio: e.target.value})} className="w-full p-2 bg-background/40 border border-white/5 rounded-lg text-[10px] font-bold cursor-pointer">
                                    <option value="1:1">1:1 Square</option>
                                    <option value="9:16">9:16 Story</option>
                                    <option value="16:9">16:9 Landscape</option>
                                </select>
                            </div>
                            <div>
                                <label className="block mb-1 font-bold text-[7px] uppercase tracking-widest text-brand-primary">{t.label_variations}</label>
                                <select value={imageOptions.count} onChange={(e) => setImageOptions({...imageOptions, count: parseInt(e.target.value)})} className="w-full p-2 bg-background/40 border border-white/5 rounded-lg text-[10px] font-bold cursor-pointer">
                                    {[1, 2, 4, 8].map(n => <option key={n} value={n}>{n} Variations</option>)}
                                </select>
                            </div>
                        </div>
                    ) : (
                        <div className="grid grid-cols-2 gap-2">
                            <div>
                                <label className="block mb-1 font-bold text-[7px] uppercase tracking-widest text-brand-primary">{t.label_ratio}</label>
                                <select value={videoOptions.aspectRatio} onChange={(e) => setVideoOptions({...videoOptions, aspectRatio: e.target.value})} className="w-full p-2 bg-background/40 border border-white/5 rounded-lg text-[10px] font-bold cursor-pointer">
                                    <option value="9:16">9:16 Portrait</option>
                                    <option value="16:9">16:9 Landscape</option>
                                </select>
                            </div>
                            <div>
                                <label className="block mb-1 font-bold text-[7px] uppercase tracking-widest text-brand-primary">{t.label_resolution}</label>
                                <select value={videoOptions.resolution} onChange={(e) => setVideoOptions({...videoOptions, resolution: e.target.value})} className="w-full p-2 bg-background/40 border border-white/5 rounded-lg text-[10px] font-bold cursor-pointer">
                                    <option value="720p">720p</option>
                                    <option value="1080p">1080p (Pro Only)</option>
                                </select>
                            </div>
                        </div>
                    )}

                    <div className="p-3 bg-background/40 border border-white/5 rounded-xl flex items-center justify-between">
                        <label className="font-bold text-[7px] text-white uppercase tracking-widest">{t.label_realism}</label>
                        <label className="relative inline-flex items-center cursor-pointer">
                            <input type="checkbox" checked={useSuperRealism} onChange={() => setUseSuperRealism(!useSuperRealism)} className="sr-only peer" />
                            <div className="w-9 h-4.5 bg-white/5 rounded-full peer peer-checked:bg-brand-primary after:content-[''] after:absolute after:top-[1.5px] after:left-[1.5px] after:bg-white after:rounded-full after:h-3.5 after:w-3.5 after:transition-all peer-checked:after:translate-x-4.5"></div>
                        </label>
                    </div>
                </div>

                <div className="space-y-2 pt-6">
                    {error && <p className="text-[#ff4db8] text-[9px] text-center font-bold tracking-tight">{error}</p>}
                    <button onClick={startGeneration} className="w-full bg-brand-primary text-white font-bold py-3 rounded-xl text-base shadow-lg hover:bg-brand-primary/80 transition-all flex items-center justify-center gap-1.5 uppercase tracking-widest">
                        <SparklesIcon className="w-4 h-4" /> {t.btn_produce}
                    </button>
                    <button onClick={() => setStep(AppStep.DEFINE_PRODUCT)} className="w-full text-content-secondary hover:text-white font-bold py-1 text-[8px] transition-all uppercase tracking-[0.2em]">{t.btn_back}</button>
                </div>
            </div>
        </div>
      </div>
    );
  };

  if (isCheckingApiKey) return <div className="min-h-screen flex items-center justify-center bg-background"><Loader message="Loading UGC Engine..." /></div>;

  if (!isApiKeyReady) {
    return (
        <div className="min-h-screen flex flex-col items-center justify-center p-6 bg-background">
            <div className="p-8 bg-surface/30 backdrop-blur-3xl border border-white/5 rounded-[2rem] shadow-xl max-w-sm text-center space-y-4">
                <div className="w-12 h-12 mx-auto">
                   <PinkDolphinLogo />
                </div>
                <div className="space-y-1">
                  <h1 className="text-xl font-bold tracking-tight text-white uppercase">{t.activation_title}</h1>
                  <p className="text-content-secondary text-sm font-light opacity-70 leading-snug">{t.activation_subtitle}</p>
                </div>
                <button onClick={handleSelectKey} className="w-full bg-white text-background font-bold py-3 px-8 rounded-full text-base hover:bg-brand-primary hover:text-white transition-all uppercase tracking-widest">
                  {t.btn_select_key}
                </button>
            </div>
        </div>
    );
  }

  const renderContent = () => {
    switch (step) {
      case AppStep.LANDING: return renderLanding();
      case AppStep.DEFINE_PRODUCT: return renderDefineProduct();
      case AppStep.GENERATE_VISUALS: return renderGenerateVisuals();
      default: return renderLanding();
    }
  };

  return (
    <div className="min-h-screen w-full flex flex-col items-center p-2 md:p-5 bg-background text-content-primary relative overflow-x-hidden">
        <div className="fixed inset-0 pointer-events-none overflow-hidden">
            <div className="absolute top-[-5%] left-[-2%] w-[50%] h-[50%] bg-brand-primary/3 rounded-full blur-[100px]"></div>
            <div className="absolute bottom-[-5%] right-[-2%] w-[40%] h-[40%] bg-[#ff4db8]/3 rounded-full blur-[100px]"></div>
