        });
        setGeneratedImages(imagesB64);
      } catch (err) { setError('Visual failed.'); } finally { setIsLoading(false); }
    } else {
      setIsLoading(true);
      startVideoLoadingRotation();
      setError(null);
      try {
        const baseForVideo = generatedImages.length > 0 ? {
            file: new File([], "temp.png"),
            data: generatedImages[0],
            mimeType: 'image/png'
        } : mainAsset;

        const videoUrl = await generateAdVideo(null, baseForVideo, customPrompt, {
          aspectRatio: videoOptions.aspectRatio as '16:9' | '9:16',
          resolution: videoOptions.resolution as '720p' | '1080p'
        });
        setGeneratedVideoUrl(videoUrl);
      } catch (err) { setError('Video failed.'); } finally { if(videoMessageInterval.current) clearInterval(videoMessageInterval.current); setIsLoading(false); }
    }
  };

  const animateGeneratedImage = async (base64: string) => {
    setGenerationMode('Video');
    setGeneratedImages([]);
    setGeneratedVideoUrl(null);
    const byteString = atob(base64);
    const ab = new ArrayBuffer(byteString.length);
    const ia = new Uint8Array(ab);
    for (let i = 0; i < byteString.length; i++) ia[i] = byteString.charCodeAt(i);
    const blob = new Blob([ab], { type: 'image/png' });
    const virtualFile = new File([blob], "ai-generated-asset.png", { type: 'image/png' });
    setMainAsset({ file: virtualFile, data: base64, mimeType: 'image/png' });

    setTimeout(() => {
        startGeneration();
    }, 500);
  };

