import { GoogleGenAI, Type, GenerateContentResponse, Part } from "@google/genai";
import { ProductInfo, AdAngle, Language, UploadedFile } from "../types";
import { brandArchetypes } from "../data/brandArchetypes";

const getGenAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateSuggestedPrompt = async (productInfo: ProductInfo, lang: Language): Promise<string> => {
  const ai = getGenAI();
  const model = "gemini-3-flash-preview";

  const prompt = `
    You are a Creative Director. Based on the following product DNA, write a single, high-end, atmospheric visual prompt for an AI image generator.

    Product: ${productInfo.name}
    Audience: ${productInfo.audience}
    USPs: ${productInfo.sellingPoints}
    Platform: ${productInfo.platform}

    The prompt should describe:
    1. A sophisticated environment/location.
    2. Specific lighting (e.g., golden hour, cinematic studio, neon noir).
    3. The overall style (e.g., high-fashion, minimalist, industrial).

    IMPORTANT: DO NOT include any text descriptions in the visual prompt itself. Focus only on the scene.
    Response should be a single paragraph of descriptive text.
  `;

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
    });
    return response.text.trim();
  } catch (error) {
    return "High-end commercial photography, professional lighting, cinematic environment.";
  }
};

export const generateAdVisuals = async (
  angle: AdAngle | null,
  mainImage: UploadedFile,
  customPrompt: string,
  options: {
    numberOfImages: number;
    aspectRatio: string;
    useSuperRealism: boolean;
    styleReference?: UploadedFile;
    headline: string;
    headlineOptions?: {
      fontSize: string;
      color: string;
      font: string;
    };
    platform: string;
    textStyle: string;
    additionalAssets?: UploadedFile[];
  }
): Promise<string[]> => {
  const ai = getGenAI();
  const model = "gemini-3-pro-image-preview";

  const ratio = options.aspectRatio.includes('1:1') ? '1:1' : 
                options.aspectRatio.includes('9:16') ? '9:16' : 
                options.aspectRatio.includes('16:9') ? '16:9' : '1:1';

  const shotTypes = [
    "Extreme Close-up Shot: High-detail macro photography focus on the product texture and craftsmanship. Minimalist artistic background.",
    "Full Body Lifestyle Shot: A person in a specific environment interacting naturally with the product. High fashion or lifestyle vibe.",
    "Upper Body / Portrait Shot: A model holding or using the product with a clear facial expression (joy, confidence, or serenity).",
    "Asymmetric Product Focus: The product stands to the side of the frame, creating high-end whitespace. Focus on the sophisticated environment and theme."
  ];

  try {
    const imagePromises = Array.from({ length: options.numberOfImages }, (_, index) => {
      const realismPart = options.useSuperRealism ? "Cinematic lighting, high-end photography, 8k resolution, photorealistic, commercial studio grade." : "";
      const currentShot = shotTypes[index % shotTypes.length];

      let textInstruction = "NO TEXT OR TYPOGRAPHY: Ensure the image is pure visual with no overlays.";
      if (options.headline) {
        textInstruction = `TEXT OVERLAY INSTRUCTION:
        Include the following text clearly in the image: "${options.headline}".
        Placement: Naturally integrated as a clean headline or stylish overlay.
        Font Style: ${options.headlineOptions?.font || 'Sans-serif, bold, modern'}.
        Font Color: ${options.headlineOptions?.color || 'White'}.
        Font Size: ${options.headlineOptions?.fontSize || 'Medium/Large'} relative to the frame.
        Ensure the text is legible and professionally styled like a high-end social media ad.`;
      }

      const fullPrompt = `
        TASK: High-end UGC Studio Creative Director.
        CONTEXT: Generating high-converting visuals for ${options.platform}.
        USER VISUAL PROMPT: ${customPrompt}
        ${angle ? `ANGLE STRATEGY: ${angle.title}` : ''}

        STRICT STYLE RULES:
        1. ${textInstruction}
        2. DIVERSITY: If humans are visible, use a DIFFERENT model/person for each variation. Varied ethnicities and ages.
        3. DIVERSITY: Each shot must be a DIFFERENT ENVIRONMENT (e.g. urban, nature, luxury interior) based on the theme.
        4. SHOT TYPE: ${currentShot}
        5. POSING: Varied positions and different facial expressions in every shot.

        TECHNICAL:
        - Incorporate the product from the provided main image seamlessly.
        - ${realismPart}
        - Maintain professional consistency with the theme/location directives.
      `;

      const parts: Part[] = [
          { inlineData: { data: mainImage.data, mimeType: mainImage.mimeType } }
      ];

      if (options.additionalAssets) {
          options.additionalAssets.forEach(asset => {
              parts.push({ inlineData: { data: asset.data, mimeType: asset.mimeType } });
          });
      }

      if (options.styleReference) {
          parts.push({ inlineData: { data: options.styleReference.data, mimeType: options.styleReference.mimeType } });
      }

      parts.push({ text: fullPrompt });

      return ai.models.generateContent({
        model: model,
        contents: { parts },
        config: { 
            imageConfig: { 
                aspectRatio: ratio as any, 
                imageSize: "1K" 
            } 
        },
      });
    });

    const responses = await Promise.all(imagePromises);
    const base64Images: string[] = [];
    for (const res of responses) {
      const part = res.candidates[0].content.parts.find(p => p.inlineData);
      if (part?.inlineData?.data) base64Images.push(part.inlineData.data);
    }
    return base64Images;
  } catch (error) {
    console.error("Visual generation failed:", error);
    throw error;
  }
};

export const generateAdVideo = async (
  angle: AdAngle | null,
  baseImage: UploadedFile | null,
  customPrompt: string,
  options: { resolution: '720p' | '1080p', aspectRatio: '16:9' | '9:16' }
): Promise<string> => {
  const ai = getGenAI();
  const model = 'veo-3.1-fast-generate-preview';

  const generationParams: any = {
    model: model,
    prompt: `Motion creative. ${customPrompt}. ${angle ? `Strategic Angle: ${angle.title}.` : ''} Cinematic movement, high-end commercial flow. The product should be the star of the scene. Smooth transitions and professional lighting.`,
    config: { 
      numberOfVideos: 1, 
      resolution: options.resolution, 
      aspectRatio: options.aspectRatio 
    }
  };

  if (baseImage) {
    generationParams.image = { 
      imageBytes: baseImage.data, 
      mimeType: baseImage.mimeType 
    };
  }

  try {
    let operation = await ai.models.generateVideos(generationParams);

    while (!operation.done) {
      await new Promise(resolve => setTimeout(resolve, 10000));
      operation = await ai.operations.getVideosOperation({ operation: operation });
    }

    const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
    if (!downloadLink) throw new Error("Video generation failed to return a link.");

    const res = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
    if (!res.ok) {
      const errorData = await res.json().catch(() => ({}));
      const msg = errorData.error?.message || `Video download failed (${res.status})`;
      throw new Error(msg);
    }

    const blob = await res.blob();
    return URL.createObjectURL(blob);
  } catch (error) {
    console.error("Video generation or download failed:", error);
    throw error;
  }
};

export const generateCaptions = async (productInfo: ProductInfo, angle: AdAngle, lang: Language): Promise<string[]> => {
  const ai = getGenAI();
  const model = "gemini-3-flash-preview";
  const langInstruction = lang === 'da' ? "Skriv teksterne på DANSK." : "Write captions in ENGLISH.";
  const prompt = `${langInstruction} Write 3 ad captions for ${productInfo.name}. Angle: ${angle.title}. Target: ${productInfo.audience}. Platform: ${productInfo.platform}. Rules: 1 short, 1 story, 1 benefit-driven.`;

  const response = await ai.models.generateContent({
    model: model,
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: { type: Type.ARRAY, items: { type: Type.STRING } },
    },
  });
  return JSON.parse(response.text.trim());
};

