    const ia = new Uint8Array(ab);
    for (let i = 0; i < byteString.length; i++) ia[i] = byteString.charCodeAt(i);
    const blob = new Blob([ab], { type: 'image/png' });
    const virtualFile = new File([blob], "ai-generated-asset.png", { type: 'image/png' });
    setMainAsset({ file: virtualFile, data: base64, mimeType: 'image/png' });

    setTimeout(() => {
